    d12_easy = [
        ("Docker Containerization", "Docker Container mang lại lợi ích kỹ thuật lớn nhất nào khi triển khai ứng dụng AI Agent lên môi trường Cloud?",
         ["Làm giảm 50% chi phí điện thoại", "Đóng gói toàn bộ mã nguồn, thư viện phụ thuộc (Dependencies như Python, PyTorch, LangGraph) và cấu hình môi trường thành một đơn vị thực thi nhất quán, đảm bảo 'chạy được ở mọi nơi'", "Tự động sửa lỗi cú pháp Python", "Tăng tốc độ gõ phím"], 1,
         "Docker loại bỏ hiện tượng 'chạy được trên máy tôi nhưng lỗi trên server' bằng cách đóng gói toàn bộ runtime environment độc lập.", "Day 12 - Slide: Docker Containerization for AI"),
        ("FastAPI Framework", "Tại sao FastAPI lại là framework web backend được ưa chuộng hàng đầu để xây dựng API phục vụ AI Agents?",
         ["Vì nó chỉ hỗ trợ giao diện đồ họa", "Hỗ trợ gốc Asynchronous (`async/await`), Tự động sinh tài liệu chuẩn OpenAPI/Swagger, Tích hợp Pydantic chặt chẽ và có hiệu năng xử lý request I/O cực cao", "Vì nó không cần kết nối mạng", "Vì nó được tạo ra bởi OpenAI"], 1,
         "FastAPI kết hợp tốc độ cao của ASGI (Starlette), xác thực dữ liệu tự động với Pydantic và hỗ trợ streaming SSE một cách tự nhiên.", "Day 12 - Slide: FastAPI for Agent Backends"),
        ("ASGI Web Servers", "Máy chủ ASGI Web Server phổ biến nhất được sử dụng để chạy ứng dụng FastAPI trong môi trường Production là gì?",
         ["Apache Tomcat", "Uvicorn (hoặc Gunicorn kết hợp Uvicorn Workers)", "Internet Explorer", "Microsoft Word"], 1,
         "Uvicorn là máy chủ ASGI siêu tốc dựa trên `uvloop` và `httptools`, tiêu chuẩn vàng để phục vụ các ứng dụng bất đồng bộ trong Python.", "Day 12 - Slide: ASGI Servers & Uvicorn"),
        ("Container Port Mapping", "Lệnh Docker `EXPOSE 8000` trong Dockerfile có ý nghĩa gì?",
         ["Tự động tăng giá token lên $8000", "Khai báo tài liệu rằng container lắng nghe các kết nối mạng trên cổng 8000 tại thời điểm thực thi", "Xóa toàn bộ các cổng mạng khác", "Giới hạn RAM ở mức 8000MB"], 1,
         "`EXPOSE` là chỉ thị tài liệu hóa cổng mạng mà ứng dụng bên trong container sẽ sử dụng để nhận request.", "Day 12 - Slide: Dockerfile Instructions"),
        ("Serverless Deployment", "Dịch vụ GCP Cloud Run hoặc AWS Fargate thuộc mô hình triển khai nào?",
         ["Mô hình máy chủ vật lý đặt tại nhà", "Serverless Container Platform: Tự động quản lý hạ tầng, tự động co giãn số lượng containers theo lưu lượng request và tự động Scale-to-Zero khi không có tải", "Mô hình mạng LAN nội bộ", "Mô hình đĩa mềm"], 1,
         "Serverless Container giải phóng kỹ sư khỏi việc quản trị cụm máy chủ, chỉ tính phí khi có request thực tế được xử lý.", "Day 12 - Slide: Serverless Container Platforms"),
        ("Health Check Endpoints", "Mục đích của việc tạo endpoint `/healthz` hoặc `/ready` trong ứng dụng FastAPI là gì?",
         ["Để người dùng kiểm tra sức khỏe cá nhân", "Cung cấp cổng kiểm tra trạng thái hoạt động (Liveness & Readiness Probes) cho Load Balancer và Kubernetes biết khi nào container sẵn sàng nhận traffic", "Để đo nhiệt độ máy chủ", "Để in báo cáo tài chính"], 1,
         "Health check endpoints cho phép hạ tầng đám mây tự động phát hiện và khởi động lại các container bị treo hoặc chưa sẵn sàng.", "Day 12 - Slide: Container Health Probes"),
        ("Environment Secrets Management", "Cách an toàn chuẩn mực nhất để nạp `OPENAI_API_KEY` vào container trên Cloud là gì?",
         ["Ghi trực tiếp chuỗi API Key vào Dockerfile bằng lệnh ENV", "Sử dụng dịch vụ Quản lý Khóa bí mật (như GCP Secret Manager hoặc AWS Secrets Manager) và inject vào container dưới dạng biến môi trường tại thời điểm runtime", "Commit API Key lên file README trên GitHub", "Gửi API Key qua tin nhắn công khai"], 1,
         "Secret Manager đảm bảo các khóa bảo mật được mã hóa ở trạng thái nghỉ và chỉ được cấp phát an toàn khi container khởi chạy.", "Day 12 - Slide: Cloud Secrets Management"),
        ("Docker Base Images", "Khi xây dựng Dockerfile cho ứng dụng AI nhẹ (không cần GPU), base image nào giúp tối ưu kích thước container nhất?",
         ["`ubuntu:latest` (dung lượng 1GB)", "`python:3.11-slim` hoặc `python:3.11-alpine`", "`windows:server-core` (dung lượng 5GB)", "`macos:monterey`"], 1,
         "Slim base images chỉ chứa các thành phần cốt lõi của Python và Linux, giúp giảm thời gian build và tải image xuống chỉ còn vài chục megabytes.", "Day 12 - Slide: Docker Base Image Selection"),
        ("CORS Middleware", "CORS (Cross-Origin Resource Sharing) trong FastAPI cần được cấu hình khi nào?",
         ["Khi người dùng tắt máy tính", "Khi giao diện Web Frontend (chạy ở domain khác, e.g. `http://localhost:3000`) cần gửi các request HTTP tới Backend API (e.g. `https://api.myai.com`)", "Khi máy chủ bị mất kết nối internet", "Khi đổi màu giao diện"], 1,
         "CORS Middleware cho phép trình duyệt web chấp nhận các cuộc gọi API xuyên miền an toàn giữa Frontend và Backend.", "Day 12 - Slide: CORS Configuration"),
        ("Graceful Shutdown", "Khái niệm 'Graceful Shutdown' (Tắt máy nhẹ nhàng) của Web Server AI có nghĩa là gì?",
         ["Rút phích cắm điện ngay lập tức", "Khi nhận tín hiệu dừng (SIGTERM), máy chủ ngừng nhận request mới nhưng tiếp tục hoàn thành nốt các luồng streaming/LLM calls đang dở dang trước khi đóng tiến trình", "Tự động xóa toàn bộ database", "Khởi động lại máy chủ ngay lập tức"], 1,
         "Graceful Shutdown ngăn chặn việc cắt đứt đột ngột các câu trả lời đang sinh dở cho người dùng khi hệ thống thực hiện cập nhật phiên bản mới.", "Day 12 - Slide: Graceful Shutdown Patterns"),
        ("Multi-Stage Builds", "Kỹ thuật 'Multi-Stage Build' trong Dockerfile mang lại lợi ích gì?",
         ["Làm cho file Dockerfile dài hơn", "Tách riêng môi trường Build (chứa trình biên dịch, công cụ cồng kềnh) và môi trường Runtime cuối cùng, giúp tạo ra container thành phẩm siêu nhẹ và an toàn hơn", "Tăng dung lượng image lên gấp 3 lần", "Chỉ chạy được trên hệ điều hành Windows"], 1,
         "Multi-Stage Build loại bỏ toàn bộ các công cụ biên dịch thừa thãi khỏi image cuối cùng, giảm thiểu bề mặt tấn công bảo mật và dung lượng lưu trữ.", "Day 12 - Slide: Multi-Stage Docker Builds"),
        ("Non-Root User in Containers", "Tại sao việc tạo và sử dụng một 'Non-Root User' (User không có quyền root) trong Dockerfile là tiêu chuẩn bảo mật bắt buộc?",
         ["Vì root user bị cấm gõ code Python", "Để nếu ứng dụng có lỗ hổng bảo mật bị khai thác (như RCE qua tool call), kẻ tấn công cũng không thể chiếm quyền điều khiển root toàn bộ máy chủ hạ tầng bên dưới", "Vì user thường chạy nhanh hơn root", "Không có lý do nào"], 1,
         "Nguyên tắc đặc quyền tối thiểu trong container ngăn chặn các cuộc tấn công thoát container (Container Escape) chiếm quyền máy chủ mẹ.", "Day 12 - Slide: Container Security & Non-Root Users"),
        (".dockerignore File", "Tệp tin `.dockerignore` có vai trò gì trong quá trình build Docker Image?",
         ["Bắt Docker bỏ qua tất cả các file mã nguồn", "Chỉ định các file và thư mục (như `.env`, `.git`, `__pycache__`, `.venv`) KHÔNG ĐƯỢC copy vào container context, giúp build nhanh hơn và bảo vệ bí mật dữ liệu", "Xóa các file rác trên máy tính", "Tự động tắt mạng"], 1,
         "`.dockerignore` ngăn chặn việc vô tình đóng gói các file bí mật môi trường hoặc các thư viện cục bộ nặng nề vào Docker image.", "Day 12 - Slide: Dockerignore Best Practices"),
        ("Container Memory Limits", "Điều gì xảy ra nếu container AI của bạn vượt quá giới hạn bộ nhớ RAM (Memory Limit) được cấp phát trên Cloud?",
         ["Máy tính tự động mua thêm RAM", "Hệ điều hành Linux sẽ kích hoạt trình giết tiến trình (OOM Killer - Out of Memory) và dừng container ngay lập tức với mã thoát 137", "Container tự động nén dữ liệu", "Tốc độ mạng bị chậm đi 10 lần"], 1,
         "Vượt quá hạn mức RAM sẽ kích hoạt OOM Killer chấm dứt tiến trình; cần tính toán kỹ lưỡng dung lượng RAM cho các mô hình embedding cục bộ.", "Day 12 - Slide: Memory Limits & OOM Killer"),
        ("TLS/HTTPS Encryption", "Tại sao việc bắt buộc cấu hình TLS/HTTPS cho API của Agent là yêu cầu tuyệt đối khi triển khai Production?",
         ["Để trang web có biểu tượng ổ khóa màu xanh đẹp mắt", "Mã hóa toàn bộ lưu lượng dữ liệu trao đổi giữa Client và Server trên đường truyền, bảo vệ nội dung prompt, API keys và thông tin nhạy cảm khỏi bị nghe lén (Man-in-the-Middle)", "Để tăng tốc độ đường truyền cáp quang", "Vì trình duyệt cấm mở HTTP"], 1,
         "HTTPS bảo vệ tính bí mật và toàn vẹn của dữ liệu trên đường truyền công cộng, ngăn chặn việc đánh cắp thông tin nhạy cảm.", "Day 12 - Slide: Transport Layer Security (TLS)")
    ]

    d12_med = [
        ("Asynchronous Streaming Architecture", "Trong FastAPI, đoạn mã nào sau đây trả về Server-Sent Events (SSE) Streaming đúng chuẩn cho Chatbot mà không bị nghẽn (Block) Server Event Loop?",
         ["Dùng `time.sleep()` trong vòng lặp đồng bộ", "Sử dụng `StreamingResponse(event_generator(), media_type='text/event-stream')` kết hợp hàm `async def event_generator()` sử dụng `async for chunk in client.chat.completions.create(stream=True):`", "Dùng hàm `print()` in ra màn hình", "Trả về toàn bộ chuỗi text trong một đối tượng JSON thông thường"], 1,
         "`StreamingResponse` kết hợp async generator cho phép truyền dữ liệu từng chunk theo thời gian thực mà không chiếm dụng tài nguyên luồng của máy chủ.", "Day 12 - Slide: Async SSE Streaming in FastAPI"),
        ("Gunicorn + Uvicorn Worker Pattern", "Khi triển khai FastAPI trên máy chủ ảo nhiều lõi (Multi-core VM), kiến trúc 'Gunicorn Process Manager + Uvicorn Workers' hoạt động như thế nào?",
         ["Chạy 10 instance của Microsoft Word", "Gunicorn đóng vai trò Master Process quản lý vòng đời và tự động phục hồi các tiến trình con; mỗi tiến trình con là một Uvicorn Worker bất đồng bộ chạy trên 1 lõi CPU độc lập để tận dụng tối đa phần cứng", "Tắt toàn bộ các lõi CPU trừ 1 lõi", "Chuyển toàn bộ code sang chạy trên GPU"], 1,
         "Mô hình Gunicorn + Uvicorn Workers nhân bản khả năng xử lý bất đồng bộ trên tất cả các lõi CPU, đạt thông lượng phục vụ hàng chục nghìn requests/giây.", "Day 12 - Slide: Production ASGI Concurrency Architecture"),
        ("Cloud Auto-Scaling Metrics", "Khi cấu hình Auto-scaling cho cụm container phục vụ AI Agent có các tác vụ I/O kéo dài (Long-lived SSE Connections), chỉ số nào phù hợp hơn CPU Utilization?",
         ["Độ sáng màn hình", "Chỉ số Số lượng Request Đồng thời trên mỗi Instance (Concurrent Requests per Container) hoặc Hàng đợi Tác vụ (Queue Depth)", "Nhiệt độ phòng máy chủ", "Số lượng file trong thư mục"], 1,
         "Với các tác vụ streaming kéo dài, CPU thường ở mức thấp nhưng số lượng kết nối đồng thời lại cao; tự động co giãn theo Concurrency phản ánh chính xác tải thực tế.", "Day 12 - Slide: Auto-Scaling Strategies for AI Workloads"),
        ("Docker Layer Caching Optimization", "Tại sao việc đặt câu lệnh `COPY requirements.txt .` và `RUN pip install ...` TRƯỚC câu lệnh `COPY . .` trong Dockerfile lại là quy chuẩn vàng?",
         ["Vì pip chỉ chạy được ở đầu file", "Tận dụng cơ chế Docker Layer Caching: Lớp cài đặt thư viện nặng nề sẽ không bị build lại trừ khi file `requirements.txt` có thay đổi, giúp tăng tốc độ build từ vài phút xuống vài giây mỗi khi sửa code", "Vì Docker cấm copy code trước", "Không có sự khác biệt nào"], 1,
         "Tận dụng tối đa bộ nhớ đệm các lớp Docker giúp quy trình CI/CD diễn ra chớp nhoáng khi lập trình viên chỉ chỉnh sửa mã nguồn ứng dụng.", "Day 12 - Slide: Docker Layer Caching Optimization"),
        ("Reverse Proxy Configuration (NGINX)", "Khi đặt NGINX phía trước FastAPI Server để phục vụ Streaming SSE, hai chỉ thị cấu hình bắt buộc phải thiết lập là gì?",
         ["`proxy_pass` và `autoindex on`", "`proxy_buffering off;` (Tắt bộ đệm để dữ liệu stream được đẩy ngay tới client) và `proxy_read_timeout 300s;` (Tăng thời gian chờ cho các câu trả lời dài của LLM)", "`ssl_ciphers none;` và `deny all;`", "`listen 80;` và `server_name localhost;`"], 1,
         "Tắt `proxy_buffering` là điều kiện tiên quyết để NGINX không giữ lại các token trong bộ nhớ đệm mà chuyển tiếp tức thì về cho trình duyệt người dùng.", "Day 12 - Slide: NGINX Reverse Proxy for SSE Streaming"),
        ("Container Memory Sizing for Embeddings", "Khi đóng gói một ứng dụng RAG cục bộ sử dụng mô hình embedding `BGE-M3` (kích thước 2.2GB) và FastAPI, container cần được cấp phát tối thiểu bao nhiêu RAM để tránh lỗi OOM?",
         ["Chỉ cần 256MB RAM", "Tối thiểu 4GB đến 6GB RAM (2.2GB cho trọng số mô hình PyTorch + 1.5GB cho bộ đệm tính toán ma trận và context buffer + 500MB cho OS và ASGI workers)", "100GB RAM", "Chỉ cần 1MB RAM"], 1,
         "Cấp phát RAM cho container AI phải tính đến kích thước nạp mô hình vào bộ nhớ, không gian đệm tính toán tensor và chi phí tài nguyên của hệ điều hành.", "Day 12 - Slide: Memory Footprint Sizing for Local Models"),
        ("Database Connection Pooling in Async Apps", "Tại sao trong ứng dụng FastAPI bất đồng bộ, việc sử dụng Async Connection Pool (như `asyncpg` hoặc `SQLAlchemy AsyncSession`) lại quan trọng hơn kết nối đồng bộ thông thường?",
         ["Vì kết nối đồng bộ làm máy tính bị tắt nguồn", "Kết nối đồng bộ truyền thống sẽ block toàn bộ Event Loop của luồng chính khi chờ database phản hồi, làm tê liệt khả năng xử lý hàng nghìn request khác; Async Connection Pool cho phép chia sẻ kết nối phi khóa", "Vì cơ sở dữ liệu cấm dùng async", "Không có sự khác biệt nào"], 1,
         "Non-blocking Async Connection Pools giữ cho Event Loop luôn lưu thông, cho phép phục vụ hàng nghìn kết nối đồng thời một cách trơn tru.", "Day 12 - Slide: Async Database Connection Pooling"),
        ("Dynamic Configuration with Pydantic BaseSettings", "Trong FastAPI, tại sao nên dùng `pydantic-settings` (`BaseSettings`) để quản lý cấu hình môi trường thay vì gọi `os.getenv()` rải rác trong code?",
         ["Vì `os.getenv()` bị cấm trong Python 3", "`BaseSettings` tự động đọc file `.env`, tự động ép kiểu dữ liệu nghiêm ngặt (int, bool, float), kiểm tra tính hợp lệ của các biến bắt buộc ngay khi khởi động (Fail-Fast) và cung cấp gợi ý kiểu dữ liệu (Autocomplete)", "Vì `BaseSettings` làm tăng tốc độ mạng", "Vì nó tự động sinh ra tiền ảo"], 1,
         "Quản lý cấu hình tập trung bằng Pydantic BaseSettings đảm bảo ứng dụng bắt lỗi thiếu cấu hình ngay khi bật server thay vì gặp lỗi bất ngờ lúc đang chạy.", "Day 12 - Slide: Type-Safe Configuration with Pydantic"),
        ("Blue-Green Deployment on Cloud Run", "Tính năng 'Traffic Splitting' (Phân chia lưu lượng) trong GCP Cloud Run hỗ trợ quy trình phát hành Blue-Green như thế nào?",
         ["Tự động đổi màu logo của ứng dụng", "Cho phép triển khai một phiên bản mới (Revision B) song song với phiên bản cũ (Revision A), định tuyến thử nghiệm 10% traffic sang B để kiểm tra chất lượng trước khi chuyển 100% lưu lượng mà không có downtime", "Xóa toàn bộ người dùng cũ", "Bắt người dùng phải chọn phiên bản bằng tay"], 1,
         "Traffic Splitting cho phép thực hiện phát hành Canary và Blue-Green một cách tức thời ở tầng hạ tầng đám mây với rủi ro bằng 0.", "Day 12 - Slide: Zero-Downtime Traffic Splitting"),
        ("Server-Sent Events vs WebSockets", "Khi nào nên lựa chọn Server-Sent Events (SSE) thay vì WebSockets cho ứng dụng AI Chatbot?",
         ["Khi cần truyền video 8K", "Khi luồng giao tiếp chủ yếu là đơn hướng (Client gửi 1 prompt lên và Server liên tục đẩy dòng token về), SSE sử dụng giao thức HTTP tiêu chuẩn, dễ dàng tương thích với Load Balancers, Firewall và hỗ trợ tự động kết nối lại (Auto-reconnect)", "Khi không có kết nối internet", "Khi cần kết nối với máy in"], 1,
         "SSE nhẹ nhàng, tận dụng hạ tầng HTTP chuẩn và tự động quản lý kết nối lại, là sự lựa chọn tối ưu cho 95% bài toán Streaming Chatbot.", "Day 12 - Slide: SSE vs WebSockets Comparison"),
        ("Container Cold Start Mitigation", "Hiện tượng 'Cold Start' (Khởi động lạnh) trong Serverless AI Container xảy ra do đâu và biện pháp giảm thiểu là gì?",
         ["Do phòng máy chủ quá lạnh vào mùa đông", "Thời gian cần thiết để hạ tầng tải Docker image nặng (vài GB) và nạp trọng số mô hình vào bộ nhớ khi có request đầu tiên; giảm thiểu bằng cách duy trì 'Minimum Instances' (e.g. `min_instances=1`) hoặc nén image tối đa", "Do máy tính bị mất điện", "Do code Python chưa được dịch sang C"], 1,
         "Duy trì một số lượng instance luôn chạy (Warm/Min Instances) loại bỏ hoàn toàn độ trễ khởi động lạnh cho người dùng đầu tiên.", "Day 12 - Slide: Mitigating Serverless Cold Starts"),
        ("API Rate Limiting Middleware", "Để bảo vệ API của Agent khỏi nguy cơ bị spam hoặc tấn công DoS, middleware nào nên được tích hợp ở tầng FastAPI?",
         ["Middleware đổi màu trang web", "Rate Limiting Middleware (như `slowapi` dựa trên thuật toán Token Bucket / Redis) giới hạn số lượng request tối đa trên mỗi IP hoặc API Key trong một đơn vị thời gian (ví dụ: 60 requests/phút)", "Middleware tắt máy tính", "Không cần middleware"], 1,
         "Rate Limiting ở tầng ứng dụng bảo vệ backend và ngân sách gọi LLM API khỏi các hành vi lạm dụng lưu lượng.", "Day 12 - Slide: API Rate Limiting Middleware"),
        ("Cloud Log Streaming & Structured JSON Logging", "Tại sao việc cấu hình thư viện `structlog` hoặc `python-json-logger` để xuất log dưới dạng 'JSON có cấu trúc' lại là chuẩn mực trên Cloud (GCP Cloud Logging / AWS CloudWatch)?",
         ["Để file log trông đẹp mắt hơn", "Các hệ thống quản trị log đám mây tự động bóc tách (Parse) các trường JSON (như `user_id`, `trace_id`, `latency_ms`), cho phép lọc, tìm kiếm và tạo biểu đồ cảnh báo một cách tức thì mà không cần viết regex phức tạp", "Vì JSON tốn ít RAM hơn text thuần", "Vì định dạng text thuần bị cấm trên đám mây"], 1,
         "Structured JSON Logging biến các dòng log thành dữ liệu có thể truy vấn được (Queryable Data), tăng tốc độ điều tra sự cố lên gấp nhiều lần.", "Day 12 - Slide: Structured JSON Logging in Production"),
        ("Stateless vs Stateful Agent Scaling", "Tại sao việc thiết kế Agent theo mô hình 'Stateless Application' (Phi trạng thái) lại là điều kiện tiên quyết để Auto-scaling trên Cloud?",
         ["Vì ứng dụng có trạng thái chạy nhanh hơn", "Vì khi ứng dụng phi trạng thái (Lưu toàn bộ Session State vào External Redis/Postgres), Load Balancer có thể tự do định tuyến bất kỳ request nào tới bất kỳ container instance nào mà không làm mất ngữ cảnh của người dùng", "Vì ứng dụng phi trạng thái không cần viết code", "Vì mô hình LLM cấm dùng bộ nhớ"], 1,
         "Tách rời trạng thái ra khỏi bộ nhớ cục bộ của container cho phép cụm máy chủ tự do co giãn từ 1 lên 100 instances một cách hoàn hảo.", "Day 12 - Slide: Stateless Application Design for Scaling"),
        ("FastAPI Background Tasks", "Trong FastAPI, tính năng `BackgroundTasks` phù hợp nhất để thực thi loại tác vụ nào sau khi đã trả lời cho người dùng?",
         ["Các tác vụ cần trả kết quả ngay trên màn hình", "Các tác vụ hậu xử lý bất đồng bộ không ảnh hưởng đến câu trả lời trực tiếp (như Ghi vết kiểm toán vào DB, Gửi email thông báo, Tính toán số liệu thống kê ngầm)", "Tắt toàn bộ máy chủ", "Xóa tài khoản người dùng"], 1,
         "BackgroundTasks cho phép giải phóng phản hồi cho người dùng ngay lập tức trong khi tiếp tục thực hiện các tác vụ phụ ở chế độ ngầm.", "Day 12 - Slide: FastAPI Background Tasks"),
        ("Docker Container Security Scanning", "Công cụ nào (như Trivy, Docker Scout, hoặc Snyk) được tích hợp vào CI/CD Pipeline để kiểm tra bảo mật container?",
         ["Công cụ kiểm tra chính tả", "Công cụ quét lỗ hổng bảo mật tự động (Vulnerability Scanner): Phân tích toàn bộ các gói phần mềm OS và thư viện Python trong Docker Image để phát hiện các CVE bảo mật đã biết trước khi deploy", "Công cụ tính tiền điện", "Công cụ đổi tên file"], 1,
         "Container Scanning tự động phát hiện và chặn đứng việc phát hành các container chứa thư viện lỗi thời có lỗ hổng bảo mật nghiêm trọng.", "Day 12 - Slide: Container Security Scanning with Trivy"),
        ("HTTP/2 Support for AI Streaming", "Tại sao việc kích hoạt giao thức HTTP/2 trên Reverse Proxy và Cloud Ingress lại mang lại lợi ích lớn cho ứng dụng AI có nhiều kết nối song song?",
         ["Vì HTTP/2 chỉ chạy được trên điện thoại", "HTTP/2 hỗ trợ Ghép kênh Đa luồng (Multiplexing) trên 1 kết nối TCP duy nhất và Nén Header (HPACK), loại bỏ tình trạng nghẽn kết nối (Head-of-Line Blocking) khi trình duyệt mở nhiều luồng streaming đồng thời", "Vì HTTP/2 tự động dịch ngôn ngữ", "Vì HTTP/2 làm giảm kích thước file ảnh"], 1,
         "HTTP/2 Multiplexing cho phép hàng chục luồng dữ liệu truyền đồng thời trên một đường ống mạng duy nhất mà không tốn chi phí mở nhiều kết nối TCP.", "Day 12 - Slide: HTTP/2 Multiplexing for AI Steaming"),
        ("API Gateway Pattern for AI Services", "Vai trò của tầng API Gateway (như Kong, Traefik, hoặc AWS API Gateway) khi đứng trước cụm dịch vụ AI là gì?",
         ["Chỉ làm nhiệm vụ đổi tên miền", "Tập trung hóa các chức năng phi nghiệp vụ: Xác thực danh tính (Authentication), Phân quyền (Authorization), Giới hạn tần suất (Rate Limiting), Định tuyến vi dịch vụ, và Thu thập số liệu giám sát tập trung", "Tự động viết code cho lập trình viên", "Thay thế toàn bộ các mô hình LLM"], 1,
         "API Gateway đóng vai trò người gác cổng thống nhất, bảo vệ các dịch vụ AI phía sau và chuẩn hóa các chính sách an ninh doanh nghiệp.", "Day 12 - Slide: API Gateway Architecture for AI")
    ]

    d12_hard = [
        ("Production Kubernetes (EKS/GKE) AI Serving Architecture", "Thiết kế một Cụm Kubernetes (EKS/GKE) đạt chuẩn Doanh nghiệp phục vụ đồng thời 50 AI Agents và Cụm Vector DB với lưu lượng 10,000 QPS. Kiến trúc hạ tầng nào đáp ứng độ sẵn sàng 99.99% và tối ưu chi phí?",
         ["Chạy toàn bộ pods trên một Node duy nhất không có Load Balancer", "Triển khai Kiến trúc Kubernetes Phân tầng: 1. NGINX Ingress Controller với SSL Termination & HTTP/2; 2. FastAPI Pods quản lý bởi Horizontal Pod Autoscaler (HPA dựa trên Custom Metrics: Request Latency & Inflight Streams); 3. Node Pools tách biệt: CPU Node Pools (Spot Instances cho Web API) và GPU Node Pools (Dedicated Instances cho Local Models/Embeddings); 4. Cluster Autoscaler + Karpenter tự động cấp phát máy chủ trong 30 giây", "Chỉ sử dụng 1 máy tính để bàn đặt tại văn phòng", "Tắt toàn bộ hệ thống dự phòng"], 1,
         "Kiến trúc Kubernetes phân tầng tách biệt tài nguyên CPU/GPU kết hợp tự động co giãn theo tải thực tế đảm bảo tính sẵn sàng tối đa với chi phí hạ tầng tối ưu.", "Day 12 - Slide: Kubernetes Infrastructure for Enterprise AI"),
        ("Zero-Downtime Rolling Updates with Long-Lived Streaming Connections", "Khi thực hiện Rolling Update một phiên bản FastAPI mới trên Kubernetes, làm thế nào để đảm bảo 1,000 người dùng đang kết nối SSE Streaming dở dang không bị ngắt kết nối đột ngột?",
         ["Xóa toàn bộ các Pod cũ ngay lập tức bằng lệnh `kubectl delete pod --force`", "Cấu hình `terminationGracePeriodSeconds: 300` trong Deployment Pod Spec kết hợp PreStop Hook: Khi có bản cập nhật mới, Kubernetes gửi tín hiệu SIGTERM, Pod cũ ngừng nhận traffic mới từ Service nhưng tiếp tục duy trì kết nối cho đến khi các luồng SSE hiện tại hoàn thành trong tối đa 300 giây", "Bắt người dùng phải đăng nhập lại từ đầu", "Chỉ cập nhật phần mềm vào dịp nghỉ lễ"], 1,
         "Graceful Termination Period dài kết hợp PreStop Hook đảm bảo các luồng streaming dài hạn hoàn tất trọn vẹn trước khi container cũ bị tiêu hủy.", "Day 12 - Slide: Zero-Downtime Rolling Updates for Long Streams"),
        ("Multi-Region Active-Active AI Ingress Routing", "Một ứng dụng AI toàn cầu phục vụ người dùng ở cả Châu Mỹ, Châu Âu và Châu Á. Thiết kế Kiến trúc Định tuyến Đa Vùng (Multi-Region Active-Active Ingress) nào đạt độ trễ mạng thấp nhất và tự động Failover?",
         ["Đặt duy nhất một máy chủ tại Hà Nội và bắt toàn thế giới kết nối về", "Sử dụng Global Anycast Load Balancer (như Cloudflare hoặc AWS Route53 Geolocation Routing / CloudFront): Tự động định tuyến request của người dùng tới Trung tâm dữ liệu gần nhất (Lowest Network Latency); nếu một vùng gặp sự cố, hệ thống DNS Health Check tự động chuyển hướng traffic sang vùng lân cận trong 3 giây mà không làm gián đoạn dịch vụ", "Yêu cầu người dùng tự chọn máy chủ bằng tay", "Tắt hệ thống mạng quốc tế"], 1,
         "Global Anycast Routing định tuyến lưu lượng thông minh tới edge location gần nhất, giảm thiểu tối đa độ trễ mạng quốc tế và cung cấp khả năng tự phục hồi thảm họa đa vùng.", "Day 12 - Slide: Multi-Region Active-Active Routing"),
        ("High-Performance vLLM & FastAPI Shared-Memory IPC", "Khi chạy một mô hình LLM cục bộ (vLLM Engine) chung máy chủ với FastAPI backend, cơ chế giao tiếp liên tiến trình (Inter-Process Communication - IPC) nào đạt độ trễ thấp nhất và triệt tiêu chi phí copy bộ nhớ?",
         ["Ghi dữ liệu ra file text trên ổ cứng rồi đọc lại", "Sử dụng POSIX Shared Memory (`/dev/shm`) hoặc Ray Distributed Memory Plasma Store kết hợp gRPC / Unix Domain Sockets: Cho phép FastAPI và vLLM chia sẻ trực tiếp các Tensor dữ liệu trong RAM mà không cần qua tầng mạng TCP/IP, giảm độ trễ IPC xuống < 1ms", "Gửi dữ liệu qua email", "Chuyển dữ liệu qua cổng USB"], 1,
         "Shared Memory IPC và Unix Domain Sockets loại bỏ hoàn toàn chi phí đóng gói gói tin mạng TCP, tối ưu hóa tốc độ truyền tensor giữa API server và Inference engine.", "Day 12 - Slide: Zero-Copy Shared Memory IPC for Local Models"),
        ("Dynamic API Key Rotation & Zero-Trust IAM Architecture", "Khi doanh nghiệp yêu cầu xoay vòng (Rotate) toàn bộ API Keys của OpenAI và Database Passwords tự động mỗi 30 ngày mà không làm gián đoạn các dịch vụ đang chạy, quy trình triển khai nào là chuẩn mực?",
         ["Mỗi tháng một lần nửa đêm kỹ sư vào sửa tay từng dòng code và restart server", "Sử dụng AWS Secrets Manager / HashiCorp Vault tích hợp Trình xoay vòng tự động (Automated Rotation Lambda): Tạo Secret phiên bản mới song song với phiên bản cũ (Dual-version Window) -> Ứng dụng tự động lắng nghe Webhook hoặc đọc Secret động không trạng thái -> Xác thực thành công phiên bản mới mới tiến hành vô hiệu hóa phiên bản cũ", "Không bao giờ đổi mật khẩu để tránh bị lỗi", "Ghi mật khẩu lên bảng công ty"], 1,
         "Quy trình xoay vòng bí mật tự động với khoảng đệm hai phiên bản (Dual-version Grace Period) đảm bảo an ninh cấp cao mà không gây ra bất kỳ gián đoạn dịch vụ nào.", "Day 12 - Slide: Automated Secret Rotation Architecture"),
        ("End-to-End Latency Budget Optimization in Microservices", "Chuỗi dịch vụ AI gồm: API Gateway -> Auth Service -> Prompt Guard Service -> RAG Service -> LLM Provider -> Output Filter. Tổng thời gian xử lý vượt quá 3 giây. Kỹ thuật tái cấu trúc kiến trúc nào đưa độ trễ về < 1.2 giây?",
         ["Bỏ qua hoàn toàn việc xác thực người dùng", "Chuyển đổi từ Kiến trúc Đồng bộ Tuần tự (Sequential Sync) sang Kiến trúc Song song & Streaming Pipeline (Pipeline Overlapping): Auth và Prompt Guard được xử lý song song với bước Fetch User Context; RAG Service kích hoạt SSE Streaming ngay khi chunk đầu tiên sẵn sàng; Tầng Guardrail lọc output theo thời gian thực trên từng cửa sổ trượt (Sliding Token Window)", "Tắt toàn bộ các microservices và gộp thành 1 file duy nhất", "Tăng giá tiền của dịch vụ lên gấp đôi"], 1,
         "Pipeline Overlapping và Streaming Sliding Guardrails biến chuỗi xử lý tuần tự thành các luồng xử lý gối đầu đồng thời, rút ngắn tối đa thời gian chờ đợi phản hồi đầu tiên.", "Day 12 - Slide: Microservice Pipeline Overlapping & Latency Optimization"),
        ("Cloud Cost Anomaly Circuit Breaking under Serverless Scaling", "Một lỗ hổng mã nguồn khiến Serverless Container tự động scale lên 1,000 instances chạy vô tận, tiêu tốn hàng nghìn USD mỗi giờ. Thiết kế Tầng Bảo vệ Ngân sách Hạ tầng (Infrastructure Cost Circuit Breaker) nào ngăn chặn thảm họa này?",
         ["Chờ đến khi thẻ tín dụng bị khóa", "Cấu hình Giới hạn Cứng (Hard Concurrency Cap e.g. `max_instances = 50`) ở cấp độ dịch vụ, kết hợp AWS/GCP Budget Alert tích hợp Cloud Function tự động thu hồi quyền IAM hoặc hạ giới hạn tài nguyên khẩn cấp khi mức tiêu thụ vượt quá 120% ngân sách ngày", "Không cho phép bất kỳ container nào chạy", "Cấm lập trình viên deploy lên đám mây"], 1,
         "Hard Concurrency Caps và cơ chế ngắt mạch chi phí tự động qua Cloud Functions bảo vệ doanh nghiệp khỏi các rủi ro tài chính do lỗi logic co giãn vô hạn.", "Day 12 - Slide: Cloud Cost Guardrails & Budget Circuit Breakers"),
        ("Secure Multi-Tenant Container Isolation", "Trong một nền tảng B2B SaaS cho phép mỗi khách hàng Doanh nghiệp tải lên các Custom Python Tools riêng, kiến trúc cô lập container nào ngăn chặn việc Tenant này đọc trộm dữ liệu của Tenant khác?",
         ["Chạy code của tất cả khách hàng chung 1 tiến trình Python", "Sử dụng Công nghệ Ảo hóa Siêu nhẹ MicroVM (như AWS Firecracker hoặc Kata Containers / gVisor) với Không gian Tên Cô lập Tuyệt đối (Per-Tenant Isolated MicroVM): Mỗi khách hàng thực thi code trong 1 MicroVM riêng biệt có kernel riêng, không có quyền truy cập mạng nội bộ và bị hủy ngay sau khi xong việc", "Chỉ cần dặn khách hàng không được xem trộm dữ liệu của nhau", "Lưu code của khách hàng vào file text công khai"], 1,
         "MicroVM Isolation (Firecracker/gVisor) cung cấp ranh giới cách ly phần cứng và kernel thực sự, triệt tiêu hoàn toàn nguy cơ rò rỉ dữ liệu giữa các khách hàng đa người dùng.", "Day 12 - Slide: Multi-Tenant MicroVM Isolation Architecture"),
        ("Distributed Cache Invalidation across Auto-Scaled AI Containers", "Khi một tài liệu tri thức trong RAG bị chỉnh sửa, làm thế nào để xóa sạch bộ nhớ đệm (Semantic Cache / In-memory Context) đồng thời trên 50 container instances đang chạy phân tán?",
         ["Khởi động lại toàn bộ 50 containers cùng lúc", "Triển khai Mạng lưới Xuất bản - Đăng ký (Redis Pub/Sub / Kafka Invalidation Topic): Khi có sự kiện cập nhật dữ liệu, một thông điệp `INVALIDATE_CACHE(doc_id)` được phát ra; toàn bộ 50 instances lắng nghe topic sẽ tự động xóa các khóa cache tương ứng trong bộ nhớ cục bộ trong vài mili-giây", "Chờ 10 ngày để cache tự hết hạn", "Gửi email cho từng container"], 1,
         "Event-Driven Cache Invalidation qua Pub/Sub đồng bộ trạng thái bộ nhớ đệm trên toàn bộ cụm máy chủ phân tán theo thời gian thực mà không cần restart dịch vụ.", "Day 12 - Slide: Distributed Cache Invalidation Patterns"),
        ("High-Concurrency Webhook Ingestion with Kafka Buffering", "Hệ thống AI Agent cần tiếp nhận 20,000 Webhook events/giây từ các đối tác thương mại điện tử nhưng backend chỉ xử lý được 2,000 events/giây. Kiến trúc Hàng đợi Đệm (Buffering & Throttling Architecture) nào đảm bảo không bị rớt dữ liệu?",
         ["Từ chối và ném lỗi 503 cho 18,000 events còn lại", "Tầng Tiếp nhận Siêu nhẹ (Lightweight Ingestion Proxy on Go/Rust): Tiếp nhận webhook, xác thực chữ ký số HMAC, đẩy ngay sự kiện vào Apache Kafka Topic với độ trễ < 2ms và trả về `HTTP 202 Accepted` cho đối tác; Cụm Worker AI phía sau sẽ tiêu thụ dữ liệu từ Kafka theo đúng năng lực xử lý", "Bắt đối tác gửi lại mỗi 1 giây", "Lưu webhook vào ổ cứng máy tính cá nhân"], 1,
         "Tách rời việc tiếp nhận (Fast Ingestion) và xử lý (Throttled Processing) qua Message Queue bảo vệ hệ thống không bị đổ vỡ khi đối mặt với các cơn sóng thần lưu lượng.", "Day 12 - Slide: High-Throughput Webhook Ingestion Architecture"),
        ("Container Build Reproducibility with Poetry & Lockfiles", "Để đảm bảo một Docker Image build hôm nay và build sau 2 năm nữa hoàn toàn giống hệt nhau 100% không bị sai lệch thư viện (Deterministic Reproducible Builds), quy trình quản lý dependencies bắt buộc phải tuân thủ điều gì?",
         ["Sử dụng lệnh `pip install langchain` không ghi rõ phiên bản", "Sử dụng công cụ quản lý khóa phiên bản nghiêm ngặt (như Poetry với `poetry.lock` hoặc `pip-compile` với Hash Checking Mode `--generate-hashes`), cố định chính xác 100% phiên bản của tất cả các thư viện con gián tiếp", "Không sử dụng thư viện nào cả", "Tự viết lại toàn bộ Python"], 1,
         "Lockfiles với cryptographic hashes đảm bảo tính bất biến và khả năng tái lập 100% của môi trường thực thi qua năm tháng, ngăn ngừa các lỗi ngầm do thư viện con tự cập nhật.", "Day 12 - Slide: Deterministic Container Builds & Lockfiles"),
        ("Edge AI Deployment with WebAssembly (Wasm)", "Khi triển khai một Agent nhỏ hỗ trợ kiểm duyệt dữ liệu chạy trực tiếp trên trình duyệt của người dùng hoặc thiết bị Edge (Edge Workers), công nghệ thực thi nào mang lại hiệu năng cao và an toàn tuyệt đối?",
         ["Cài đặt toàn bộ hệ điều hành Ubuntu vào trình duyệt", "Biên dịch mã nguồn và mô hình AI nhỏ (Small Transformers) sang WebAssembly (Wasm / ONNX Web Runtime): Chạy với tốc độ gần bằng mã máy nguyên bản (Near-native Speed) trong môi trường Sandbox bảo mật của trình duyệt mà không cần cài đặt phần mềm phụ trợ", "Chạy code bằng file `.bat`", "Gửi toàn bộ máy chủ cho khách hàng"], 1,
         "WebAssembly (Wasm) cho phép mang sức mạnh tính toán AI an toàn, hiệu năng cao tới trực tiếp thiết bị đầu cuối của người dùng mà không phụ thuộc vào máy chủ trung tâm.", "Day 12 - Slide: WebAssembly & Edge AI Runtime Architecture")
    ]
