    # ==========================================
    # DAY 13: Monitoring, Logging & Observability
    # ==========================================
    d13_easy = [
        ("Observability Foundations", "Ba trụ cột chính của Observability (Khả năng quan sát) trong kỹ nghệ phần mềm và AI là gì?",
         ["CPU, RAM, Ổ cứng", "Metrics (Số liệu đo lường), Logs (Nhật ký sự kiện) và Traces (Vết phân tán)", "Màn hình, Chuột, Bàn phím", "HTML, CSS, JavaScript"], 1,
         "Metrics, Logs và Traces là 3 nguồn dữ liệu quan sát cốt lõi giúp kỹ sư hiểu rõ trạng thái vận hành bên trong của hệ thống phức tạp.", "Day 13 - Slide: Three Pillars of Observability"),
        ("OpenTelemetry Standard", "OpenTelemetry (OTel) là một chuẩn mở phục vụ mục đích gì trong hệ thống AI?",
         ["Vẽ sơ đồ mạch điện", "Chuẩn hóa việc thu thập, xử lý và xuất khẩu các dữ liệu Telemetry (Metrics, Traces, Logs) một cách độc lập với nhà cung cấp (Vendor-neutral)", "Tự động dịch văn bản", "Đếm số lần người dùng click chuột"], 1,
         "OpenTelemetry cung cấp bộ API và SDK chuẩn mực quốc tế để thu thập dữ liệu giám sát cho các hệ thống phân tán và ứng dụng AI.", "Day 13 - Slide: OpenTelemetry Standard"),
        ("Distributed Tracing", "Trong Distributed Tracing, 'Trace' và 'Span' có mối quan hệ như thế nào?",
         ["Trace và Span là hai file độc lập không liên quan", "Trace đại diện cho toàn bộ hành trình xử lý của một yêu cầu đầu-cuối (End-to-end Request); Span là một đơn vị công việc riêng lẻ (ví dụ: 1 API call, 1 DB query) cấu thành nên Trace", "Span lớn hơn Trace 100 lần", "Trace chỉ dùng cho hình ảnh"], 1,
         "Một Trace là một cây có hướng (DAG) bao gồm nhiều Spans lồng nhau thể hiện chi tiết từng mắt xích thực thi trong hệ thống.", "Day 13 - Slide: Traces vs Spans Architecture"),
        ("LLM Observability Tools", "Các nền tảng nào sau đây được thiết kế chuyên biệt cho việc giám sát và đánh giá ứng dụng LLM (LLM-native Observability)?",
         ["LangSmith, Phoenix (Arize AI), Langfuse", "Photoshop, Lightroom, Canva", "Excel, Word, PowerPoint", "VLC Media Player, Windows Media Player"], 0,
         "LangSmith, Phoenix và Langfuse là các giải pháp hàng đầu cung cấp cái nhìn chi tiết vào chuỗi suy luận (Run Trees), chi phí token và chất lượng của LLM.", "Day 13 - Slide: LLM Observability Ecosystem"),
        ("Percentile Latency (p95/p99)", "Tại sao khi theo dõi độ trễ hệ thống AI, chỉ số phân vị p95 hoặc p99 lại có giá trị hơn rất nhiều so với Độ trễ trung bình (Average Latency)?",
         ["Vì p95 dễ tính toán hơn", "Độ trễ trung bình thường che giấu các trường hợp xử lý cực kỳ chậm (Long-tail latency); p95/p99 phản ánh chính xác trải nghiệm của 5% hoặc 1% người dùng gặp phải phản hồi chậm nhất", "Vì p95 luôn bằng 0", "Vì p95 là công thức của OpenAI"], 1,
         "Chỉ số phân vị p95/p99 phản ánh điểm nghẽn nghiêm trọng nhất của hệ thống, giúp phát hiện các truy vấn bị treo hoặc lỗi ngầm.", "Day 13 - Slide: Percentile Latency Metrics (p50, p95, p99)"),
        ("Token Usage Metrics", "Hai chỉ số số lượng token cơ bản bắt buộc phải theo dõi trong mọi dashboard vận hành LLM là gì?",
         ["Số ký tự viết hoa và số ký tự viết thường", "Prompt Tokens (Input Tokens tiêu tốn) và Completion Tokens (Output Tokens sinh ra)", "Số dòng code và số file", "Số lượng ảnh và số lượng video"], 1,
         "Theo dõi độc lập Input và Output tokens là nền tảng để tính toán chi phí tài chính và phát hiện các trường hợp prompt bị phình to bất thường.", "Day 13 - Slide: Token Telemetry & Budgeting"),
        ("HTTP Error Metrics", "Mã lỗi HTTP 5xx xuất hiện trên dashboard giám sát LLM API Gateway cảnh báo vấn đề gì?",
         ["Người dùng nhập sai mật khẩu", "Lỗi nội bộ phía máy chủ (Server-side Error / LLM Provider Outage / Backend Crash)", "Người dùng không có tiền trong tài khoản", "Đường truyền mạng của người dùng bị ngắt"], 1,
         "HTTP 5xx là tín hiệu khẩn cấp về sự cố hạ tầng máy chủ hoặc nhà cung cấp mô hình bị sập cần đội ngũ kỹ sư can thiệp ngay lập tức.", "Day 13 - Slide: Error Rate Monitoring (4xx vs 5xx)"),
        ("LLM Tracing Context", "Thông tin nào sau đây BẮT BUỘC phải được ghi lại trong một Span gọi LLM chuẩn?",
         ["Màu sắc màn hình người dùng", "Model Name (e.g. `gpt-4o`), Temperature, Prompt Messages, Output Text, Prompt/Completion Token Counts, và Latency Duration", "Tên của lập trình viên viết code", "Số tài khoản ngân hàng của khách hàng"], 1,
         "Ghi nhận đầy đủ siêu tham số, nội dung và số lượng token cho phép tái lập chính xác mọi lượt gọi mô hình phục vụ điều tra sự cố.", "Day 13 - Slide: OpenTelemetry Semantic Conventions for Generative AI"),
        ("Feedback Metric Logging", "Làm thế nào để gắn kết (Correlate) phản hồi của người dùng (Thumbs Up/Down) với lượt gọi LLM tương ứng trong hệ thống Tracing?",
         ["Yêu cầu người dùng tự nhớ mã số", "Gửi kèm `trace_id` hoặc `run_id` duy nhất từ Backend về Frontend; khi người dùng bấm Feedback, gửi lại `trace_id` đó để gắn Tag trực tiếp vào bản ghi Trace trong hệ thống giám sát", "Tự động gán phản hồi cho lượt gọi gần nhất", "Không thể gắn kết được"], 1,
         "Sử dụng Trace ID làm khóa liên kết cho phép lọc nhanh tất cả các Trace bị đánh giá tiêu cực để phân tích nguyên nhân thất bại.", "Day 13 - Slide: User Feedback Telemetry Correlation"),
        ("Dashboard Visualization", "Grafana và Datadog thường được sử dụng trong hệ thống AI cho mục đích gì?",
         ["Soạn thảo văn bản", "Xây dựng các bảng điều khiển trực quan hóa thời gian thực (Dashboards) hiển thị biểu đồ về RPM, TPM, p95 Latency, Tỉ lệ lỗi và Chi phí token", "Chơi game trực tuyến", "Chỉnh sửa video"], 1,
         "Grafana và Datadog là các công cụ giám sát trực quan hàng đầu giúp đội ngũ kỹ thuật theo dõi sức khỏe hệ thống theo thời gian thực.", "Day 13 - Slide: Monitoring Dashboards with Grafana"),
        ("PII Masking in Logs", "Tại sao việc che giấu thông tin cá nhân (PII Redaction) TRƯỚC KHI ghi log vào hệ thống tập trung là yêu cầu tuân thủ bắt buộc?",
         ["Để file log nhẹ hơn", "Ngăn chặn việc dữ liệu nhạy cảm của khách hàng bị lộ cho các nhân viên không có thẩm quyền hoặc vi phạm các đạo luật bảo vệ quyền riêng tư (GDPR/HIPAA)", "Để làm cho log trông bí ẩn", "Vì hệ thống log cấm chứa chữ cái"], 1,
         "Dữ liệu log thường được truy cập bởi nhiều kỹ sư và lưu trữ dài hạn; làm sạch PII tại nguồn bảo vệ doanh nghiệp khỏi rủi ro rò rỉ thông tin.", "Day 13 - Slide: PII Masking in Telemetry Pipelines"),
        ("LangSmith Run Trees", "Cấu trúc 'Run Tree' trong LangSmith hiển thị thông tin gì?",
         ["Hình ảnh cây cối trong tự nhiên", "Cấu trúc phân cấp hình cây thể hiện chi tiết từng bước thực thi của Agent: Từ User Input -> Chain -> Retriever -> LLM Call -> Tool Execution -> Final Output", "Danh sách các file trong ổ cứng", "Lịch sử mua hàng của công ty"], 1,
         "Run Tree trực quan hóa toàn bộ dòng chảy suy luận và luồng dữ liệu trung gian qua từng nút của Agent, giúp việc gỡ lỗi trở nên trực quan và dễ dàng.", "Day 13 - Slide: LangSmith Run Trees & Nested Spans"),
        ("Cost Anomaly Alerts", "Hệ thống Cảnh báo Bất thường Chi phí (Cost Anomaly Alerting) kích hoạt khi nào?",
         ["Khi công ty hết tiền", "Khi tốc độ tiêu tốn chi phí token trong 1 giờ vượt quá một ngưỡng độ lệch chuẩn định trước so với mức trung bình lịch sử", "Khi giá vàng tăng", "Vào cuối mỗi năm tài chính"], 1,
         "Cảnh báo chi phí bất thường giúp phát hiện ngay các sự cố vòng lặp vô hạn hoặc tấn công lạm dụng tài nguyên trước khi gây thiệt hại tài chính nặng nề.", "Day 13 - Slide: Real-time Cost Anomaly Alerting"),
        ("Log Aggregation", "Elasticsearch, Logstash, Kibana (ELK Stack) hoặc Grafana Loki đóng vai trò gì trong hạ tầng AI?",
         ["Lưu trữ video bài giảng", "Thu thập, lập chỉ mục và cung cấp công cụ tìm kiếm tập trung trên hàng triệu dòng log phân tán từ các container máy chủ", "Tự động gõ prompt cho người dùng", "Chạy mô hình học sâu"], 1,
         "Hệ thống Log Aggregation tập trung hóa toàn bộ nhật ký từ hàng trăm máy chủ, cho phép truy vấn và tra cứu sự cố trong vài giây.", "Day 13 - Slide: Centralized Log Aggregation"),
        ("SLA/SLO Metrics", "Trong quản trị vận hành AI, SLO (Service Level Objective) được định nghĩa là gì?",
         ["Hợp đồng pháp lý phạt tiền", "Mục tiêu định lượng nội bộ mà đội ngũ kỹ thuật cam kết duy trì cho hệ thống (ví dụ: 99.5% requests có TTFT < 1.0s và Tỉ lệ lỗi < 0.1%)", "Số lượng nhân viên trong ca trực", "Tên của mô hình AI"], 1,
         "SLO là kim chỉ nam kỹ thuật giúp cân bằng giữa tốc độ phát triển tính năng mới và độ ổn định tin cậy của dịch vụ.", "Day 13 - Slide: SLAs, SLOs, and SLIs for AI")
    ]

    d13_med = [
        ("Distributed Context Propagation", "Cơ chế 'Context Propagation' (Lan truyền Ngữ cảnh trong OpenTelemetry) truyền `trace_id` và `span_id` qua các ranh giới mạng Microservices bằng cách nào?",
         ["Gửi email giữa các máy chủ", "Inject các ID định danh vào HTTP Headers chuẩn (W3C Trace Context e.g. `traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01`) khi gọi API giữa các dịch vụ", "Lưu vào file text trên USB", "Dùng sóng radio"], 1,
         "W3C Trace Context Header cho phép nối liền các Span độc lập trên nhiều máy chủ khác nhau thành một Trace duy nhất hoàn chỉnh.", "Day 13 - Slide: W3C Trace Context & Propagation"),
        ("Phoenix Tracing for Evaluations", "Nền tảng Phoenix (Arize AI) cung cấp khả năng đánh giá liên tục (Continuous Evals) trên dữ liệu Trace thực tế như thế nào?",
         ["Thuê người ngồi chấm điểm từng dòng log", "Tự động lấy mẫu các Trace trên Production, chạy các bộ đánh giá tự động (Evals như QA Correctness, Hallucination, Toxicity) và trực quan hóa các cụm lỗi (Error Clusters) bằng UMAP Projection", "Xóa các trace bị lỗi để giữ điểm cao", "In dữ liệu trace ra giấy"], 1,
         "Phoenix kết hợp Tracing và LLM-assisted Evaluation giúp tự động phát hiện các cụm chủ đề mà mô hình đang trả lời kém trên dữ liệu người dùng thực.", "Day 13 - Slide: Phoenix AI Observability & Evals"),
        ("Token Cost Allocation Tagging", "Để tính toán chính xác chi phí LLM cho từng Khách hàng Doanh nghiệp (Tenant Cost Allocation), kỹ thuật gắn thẻ (Tagging) nào được áp dụng ở tầng Tracing?",
         ["Mỗi khách hàng dùng 1 máy tính riêng", "Gắn các thuộc tính ngữ nghĩa (`tenant_id`, `user_tier`, `feature_name`) vào Metadata của Span OpenTelemetry; hệ thống giám sát sẽ tổng hợp chi phí token theo từng Tag tương ứng", "Chia đều tổng hóa đơn cho tất cả khách hàng", "Không cần tính chi phí"], 1,
         "Attribute Tagging trên Span cho phép bóc tách chi tiết biên lợi nhuận và mức tiêu thụ tài nguyên của từng khách hàng và tính năng sản phẩm.", "Day 13 - Slide: Semantic Attributes & Cost Attribution"),
        ("Sampling Strategies in High-Volume Tracing", "Khi hệ thống xử lý 100 triệu requests/ngày, tại sao không nên lưu trữ 100% Trace và chiến lược 'Tail-based Sampling' giải quyết bài toán này ra sao?",
         ["Vì hệ thống tracing cấm lưu nhiều dữ liệu", "Lưu 100% gây tốn kém chi phí hạ tầng khổng lồ; Tail-based Sampling phân tích toàn bộ Trace ở cuối luồng: Luôn giữ lại 100% các Trace bị lỗi (Error) hoặc có độ trễ cao (High Latency), và chỉ lấy mẫu 1% các Trace thành công bình thường", "Xóa ngẫu nhiên 99% dữ liệu mà không cần kiểm tra", "Chỉ ghi trace vào ngày chủ nhật"], 1,
         "Tail-based Sampling đảm bảo không bao giờ bỏ sót các sự cố bất thường trong khi giảm tới 90% chi phí lưu trữ dữ liệu giám sát.", "Day 13 - Slide: Head vs Tail-Based Tracing Sampling"),
        ("Semantic Conventions for LLMs", "Chuẩn OpenTelemetry Semantic Conventions for Generative AI quy định tên thuộc tính chuẩn nào để ghi nhận số lượng token đầu vào?",
         ["`input_word_count`", "`gen_ai.usage.input_tokens` (hoặc `llm.usage.prompt_tokens`)", "`token_number_v1`", "`system_token_int`"], 1,
         "Quy chuẩn ngữ nghĩa OTel thống nhất tên thuộc tính trên toàn ngành, cho phép chuyển đổi linh hoạt giữa các nhà cung cấp giám sát mà không cần sửa code.", "Day 13 - Slide: OTel GenAI Semantic Conventions"),
        ("Alerting Fatigue & Dynamic Thresholds", "Tại sao việc sử dụng Ngưỡng Cảnh báo Tĩnh (Static Threshold e.g. 'Báo động khi có hơn 100 lỗi/phút') thường gây ra cảnh báo giả vào ban ngày hoặc bỏ sót lỗi vào ban đêm?",
         ["Vì máy chủ bị thay đổi vị trí", "Lưu lượng truy cập thực tế biến động theo chu kỳ ngày/đêm (Seasonality); giải pháp là sử dụng Ngưỡng Động (Dynamic/Adaptive Thresholds) dựa trên Tỉ lệ Phần trăm Lỗi (Error Rate %) hoặc độ lệch chuẩn thống kê (Z-score)", "Vì đồng hồ máy chủ bị chạy sai", "Không có lý do nào"], 1,
         "Ngưỡng động thích ứng theo lưu lượng thời gian thực giúp phát hiện sự cố chính xác cả trong giờ cao điểm lẫn lúc nửa đêm vắng khách.", "Day 13 - Slide: Dynamic Thresholds & Alert Hygiene"),
        ("End-to-End Latency Waterfalls", "Khi phân tích một 'Latency Waterfall Chart' của một phiên RAG phức tạp, điều gì giúp kỹ sư nhận diện ngay thành phần gây nghẽn (Bottleneck)?",
         ["Thanh biểu đồ có màu đẹp nhất", "Thanh Span nằm ngang dài nhất trong biểu đồ thời gian thể hiện tác vụ chiếm nhiều mili-giây nhất (ví dụ: Vector DB Search tốn 1.5s trong khi LLM chỉ tốn 300ms)", "Thanh Span có tên ngắn nhất", "Số lượng ký tự trong Span"], 1,
         "Waterfall Chart trực quan hóa thời gian bắt đầu và kết thúc của từng Span, cho phép phát hiện ngay các tác vụ chạy tuần tự không cần thiết hoặc bị treo.", "Day 13 - Slide: Latency Waterfall Analysis"),
        ("Structured Error Taxonomy in AI Logs", "Một bảng phân loại mã lỗi có cấu trúc chuẩn cho ứng dụng AI cần phân biệt rõ những nhóm nguyên nhân nào?",
         ["Lỗi của sếp và lỗi của nhân viên", "1. `PROVIDER_RATE_LIMIT` (429), 2. `PROVIDER_DOWNTIME` (5xx/Timeout), 3. `INPUT_GUARDRAIL_BLOCKED` (Vi phạm an toàn), 4. `OUTPUT_PARSE_ERROR` (Lỗi JSON Schema), 5. `TOOL_EXECUTION_FAILED` (Lỗi API bên thứ ba)", "Lỗi máy tính và lỗi màn hình", "Lỗi bàn phím và lỗi chuột"], 1,
         "Phân loại lỗi chuẩn mực giúp tự động định tuyến sự cố tới đúng đội ngũ phụ trách (Đội hạ tầng, Đội prompt hay Đội đối tác tích hợp).", "Day 13 - Slide: AI Error Taxonomy & Diagnostics"),
        ("Real-time Dashboard: Token Velocity", "Chỉ số 'Token Generation Velocity' (Tốc độ sinh token trung bình, tính bằng tokens/giây trên mỗi stream) phản ánh khía cạnh nào của trải nghiệm người dùng?",
         ["Độ sáng của màn hình", "Độ mượt mà của trải nghiệm đọc trực tiếp (Streaming Smoothness): Nếu tốc độ sinh < 10 tokens/giây, người dùng sẽ cảm thấy bot phản hồi giật cục và chậm chạp", "Dung lượng pin tiêu thụ", "Số lượng người đang online"], 1,
         "Token Velocity đo lường tốc độ hiển thị từ, yếu tố quyết định cảm giác nhanh nhạy của ứng dụng tương tác thời gian thực.", "Day 13 - Slide: Token Generation Velocity & Perceived Speed"),
        ("Instrumentation: Auto vs Manual", "Sự khác biệt giữa Auto-Instrumentation (như `openllmetry` tự động bọc SDK) và Manual Instrumentation trong ứng dụng AI là gì?",
         ["Auto-instrumentation chỉ chạy được trên điện thoại", "Auto-instrumentation tự động chèn trace vào tất cả các lệnh gọi OpenAI/LangChain chỉ với 1 dòng code; Manual Instrumentation cho phép lập trình viên chủ động gắn thêm các Custom Spans và Business Metrics đặc thù của nghiệp vụ", "Manual instrumentation không dùng code", "Cả 2 đều giống hệt nhau"], 1,
         "Kết hợp Auto-instrumentation (cho hạ tầng cơ bản) và Manual instrumentation (cho logic nghiệp vụ sâu) mang lại độ phủ quan sát hoàn hảo.", "Day 13 - Slide: Automated vs Manual Instrumentation"),
        ("Logging Prompt Inputs Safely", "Khi ghi lại nội dung User Prompt vào hệ thống Observability phục vụ phân tích, quy trình bảo mật bắt buộc phải áp dụng là gì?",
         ["Lưu công khai không cần mã hóa", "Chạy qua Tầng Ẩn danh Tự động (Automated Sanitizer/Presidio) để bôi đen toàn bộ mật khẩu, số thẻ tín dụng, thông tin y tế, và mã hóa dữ liệu log ở trạng thái nghỉ (Encryption at Rest)", "Xóa toàn bộ chữ cái nguyên âm", "Chỉ ghi log của người dùng nước ngoài"], 1,
         "Làm sạch dữ liệu nhạy cảm trước khi đưa vào kho lưu trữ giám sát bảo vệ hệ thống khỏi các nguy cơ rò rỉ dữ liệu nội bộ.", "Day 13 - Slide: Safe Prompt Logging Protocols"),
        ("Observability in Multi-Agent Loops", "Trong một hệ sinh thái Multi-Agent, làm thế nào để theo dõi số bước lặp và chi phí tích lũy của toàn bộ phiên làm việc?",
         ["Đếm số dòng code trong chương trình", "Sử dụng Root Trace Span bọc toàn bộ phiên làm việc, tự động tích lũy và cập nhật bộ đếm `total_steps` và `cumulative_cost_usd` sau mỗi lần một Agent con hoàn thành một Sub-span", "Bắt người dùng tự tính tiền", "Khởi động lại máy chủ sau mỗi bước"], 1,
         "Root Span đóng vai trò bộ tích lũy trạng thái toàn cục, cung cấp bức tranh tổng thể về chi phí và số bước thực thi của toàn bộ hệ thống tác tử.", "Day 13 - Slide: Multi-Agent Telemetry Aggregation"),
        ("Synthetics Monitoring for AI APIs", "Phương pháp 'Synthetics Monitoring' (Giám sát Nhân tạo) cho hệ thống AI hoạt động như thế nào?",
         ["Hỏi ý kiến của robot", "Định kỳ (e.g. mỗi 1 phút) tự động phát các câu hỏi kiểm thử mẫu (Canary Queries) tới hệ thống Production để đo lường độ sẵn sàng (Uptime), TTFT và độ chính xác của câu trả lời trước khi người dùng thực phát hiện lỗi", "Chỉ kiểm tra khi có khách hàng phàn nàn", "Tắt toàn bộ hệ thống để bảo trì"], 1,
         "Synthetics Monitoring chủ động phát hiện các sự cố suy thoái dịch vụ 24/7 ngay cả trong những khung giờ không có người dùng thực truy cập.", "Day 13 - Slide: Synthetic Canary Monitoring"),
        ("Log Retention Policies & Compliance", "Chính sách 'Log Retention Policy' (Thời hạn lưu trữ nhật ký) cho dữ liệu hội thoại AI cần được thiết kế dựa trên tiêu chuẩn nào?",
         ["Lưu trữ vĩnh viễn không bao giờ xóa", "Cân bằng giữa Yêu cầu Pháp lý/Tuân thủ (ví dụ: Lưu trữ 90 ngày cho mục đích thanh tra an ninh) và Quyền riêng tư của người dùng (Tự động xóa sau thời hạn quy định để giảm rủi ro pháp lý)", "Xóa toàn bộ log sau đúng 1 giây", "Lưu log trên đĩa mềm"], 1,
         "Chính sách lưu trữ nhật ký có thời hạn rõ ràng bảo vệ doanh nghiệp khỏi các trách nhiệm pháp lý kéo dài và tối ưu hóa chi phí lưu trữ đám mây.", "Day 13 - Slide: Log Retention & Compliance Policies"),
        ("Prometheus & OpenTelemetry Collector", "Trong kiến trúc giám sát hiện đại, OpenTelemetry Collector đóng vai trò trung gian như thế nào giữa Ứng dụng AI và Prometheus/Datadog?",
         ["Tự động viết code cho ứng dụng", "Đóng vai trò là trạm trung chuyển (Proxy): Tiếp nhận dữ liệu Telemetry từ ứng dụng, thực hiện xử lý/lọc/bỏ PII (Processors), và phân phối (Export) đồng thời tới nhiều đích giám sát khác nhau (Prometheus cho metrics, Jaeger cho traces, Loki cho logs)", "Chỉ làm nhiệm vụ in báo cáo", "Thay thế hoàn toàn cơ sở dữ liệu"], 1,
         "OTel Collector tách rời mã nguồn ứng dụng khỏi hạ tầng giám sát, cho phép thay đổi hệ thống backend giám sát mà không cần sửa đổi mã nguồn ứng dụng.", "Day 13 - Slide: OpenTelemetry Collector Architecture"),
        ("Tracing Tool Execution Failures", "Khi một Tool Call bên trong Agent bị lỗi (e.g. `ConnectionRefusedError`), Span của Tool đó cần được gắn trạng thái và thông tin gì?",
         ["Gắn cờ thành công và xóa thông báo lỗi", "Thiết lập `span.set_status(StatusCode.ERROR)` kèm theo Exception Type, Error Message và Stacktrace vào sự kiện Span Event để hiển thị màu đỏ trên Dashboard", "Tắt toàn bộ tiến trình tracing", "Gửi tin nhắn chúc mừng cho lập trình viên"], 1,
         "Đánh dấu trạng thái lỗi và ghi lại chi tiết ngoại lệ trên Span giúp kỹ sư nhanh chóng lọc ra các mắt xích công cụ bị hỏng trong chuỗi hành động.", "Day 13 - Slide: Error Tracking in Tool Spans"),
        ("Log-to-Metric Conversion", "Kỹ thuật 'Metric Extraction from Logs' (Trích xuất chỉ số từ log) trên CloudWatch/Datadog cho phép làm gì?",
         ["Biến file log thành video", "Tự động quét các trường dữ liệu số học trong log JSON (như `tokens_used`) để sinh ra các đồ thị Metric đo lường thời gian thực mà không cần viết thêm code đo đạc trong ứng dụng", "Xóa toàn bộ các dòng log chữ", "Tự động dịch log sang tiếng Anh"], 1,
         "Trích xuất metric từ nhật ký có cấu trúc là phương pháp nhanh chóng để xây dựng các biểu đồ giám sát từ dữ liệu log sẵn có.", "Day 13 - Slide: Metric Extraction from Structured Logs"),
        ("Correlating LLM Hallucinations with Traces", "Khi một câu trả lời bị người dùng gắn cờ 'Ảo giác', quy trình điều tra sự cố (Root Cause Triage) trên hệ thống Tracing cần kiểm tra những gì?",
         ["Đổ lỗi hoàn toàn cho người dùng", "1. Kiểm tra Prompt gửi lên mô hình có chứa đầy đủ Context từ bước Retrieval không; 2. Kiểm tra Similarity Score của các chunks; 3. Kiểm tra siêu tham số Temperature; 4. Kiểm tra xem LLM có bị hiện tượng Attention Dilution không", "Khởi động lại toàn bộ máy tính công ty", "Xóa câu trả lời đó khỏi database"], 1,
         "Điều tra có hệ thống trên Trace giúp phân lập chính xác lỗi thuộc về khâu trích xuất dữ liệu (Retrieval Failure) hay khâu lập luận của mô hình (Model Reasoning Failure).", "Day 13 - Slide: Hallucination Root Cause Analysis via Traces")
    ]

    d13_hard = [
        ("Enterprise-Grade End-to-End AI Observability Architecture", "Thiết kế một Hạ tầng Observability Toàn diện phục vụ 100 AI Microservices và Cụm Multi-Agent xử lý 50 triệu requests/ngày. Kiến trúc phân tán nào đáp ứng chuẩn Zero-Data-Loss, Bảo mật PII và Chi phí Tối ưu?",
         ["Ghi toàn bộ log vào các file `.txt` cục bộ trên từng máy chủ", "Triển khai Kiến trúc OpenTelemetry Tiêu chuẩn: 1. Auto + Manual Instrumentation trên các dịch vụ AI phát OTLP data qua gRPC; 2. Cụm OpenTelemetry Collector phân tán thực hiện Tail-based Sampling (lưu 100% lỗi, 2% thành công) và PII Redaction Pipeline tại chỗ; 3. Phân luồng dữ liệu: Metrics nạp vào Prometheus/M3DB, Traces nạp vào Jaeger/Tempo, Logs nạp vào Grafana Loki; 4. Nền tảng Đánh giá Tự động (Phoenix/LangSmith) phân tích chất lượng ngầm; 5. PagerDuty Alerting tích hợp Slack", "Chỉ mua tài khoản giám sát gói rẻ nhất và tắt bớt máy chủ", "Không cần giám sát vì hệ thống đã được kiểm thử trước"], 1,
         "Kiến trúc OpenTelemetry phân tầng với bộ xử lý Collector trung gian, lấy mẫu thông minh và phân tách kho lưu trữ chuyên dụng là giải pháp chuẩn mực cấp doanh nghiệp toàn cầu.", "Day 13 - Slide: Enterprise-Grade AI Observability Architecture"),
        ("Real-time Semantic Drift & Concept Drift Observability Engine", "Làm thế nào để xây dựng một Engine Giám sát Trôi lệch Ngữ nghĩa (Real-time Semantic Drift Detector) phát hiện sự thay đổi trong hành vi đặt câu hỏi của người dùng mà không cần nhãn dữ liệu con người?",
         ["Chờ người dùng gửi email phàn nàn", "Trích xuất Embedding Vectors của tất cả User Queries trên Production theo từng cửa sổ thời gian (e.g. Cửa sổ trượt 24h) -> Sử dụng thuật toán Maximum Mean Discrepancy (MMD) hoặc Wasserstein Distance đối sánh phân phối vector hiện tại với Phân phối Baseline chuẩn; nếu khoảng cách vượt ngưỡng thống kê $p < 0.01$, kích hoạt cảnh báo Semantic Drift", "Đếm số lượng chữ cái trong mỗi câu hỏi", "Tự động khóa toàn bộ người dùng mới"], 1,
         "Sử dụng khoảng cách Wasserstein hoặc MMD trên không gian embedding cho phép phát hiện sự dịch chuyển phân phối dữ liệu đầu vào một cách tự động và chuẩn xác về mặt toán học.", "Day 13 - Slide: Statistical Embedding Drift Detection Engines"),
        ("Distributed Trace Reconstruction in Asynchronous Agent Mesh", "Trong một hệ thống Multi-Agent phức tạp trao đổi thông điệp bất đồng bộ qua Kafka Topics và Webhooks kéo dài 3 ngày, làm thế nào để tái hiện cây vết Trace hoàn chỉnh mà không bị đứt đoạn ngữ cảnh?",
         ["Không thể tái hiện được vì thời gian quá dài", "Áp dụng Mô hình Gắn kết Ngữ cảnh Bất đồng bộ (Asynchronous Context Propagation via Metadata Envelopes): Mọi message trong Kafka đính kèm `trace_id`, `parent_span_id`, `causality_link_id` trong Header; Hệ thống Tracing sử dụng 'Span Links' (Liên kết Span lỏng) thay vì quan hệ Cha-Con đồng bộ truyền thống, cho phép nối kết các phiên làm việc cách nhau nhiều ngày vào cùng một đồ thị sự kiện", "Tắt toàn bộ hàng đợi Kafka và chuyển sang gọi hàm trực tiếp", "Chỉ ghi lại 10 giây đầu tiên"], 1,
         "Span Links trong OpenTelemetry cho phép mô hình hóa các mối quan hệ nhân quả bất đồng bộ kéo dài nhiều ngày mà không vi phạm các ràng buộc của mô hình cây đơn luồng.", "Day 13 - Slide: Asynchronous Distributed Tracing & Span Links"),
        ("Automated Root Cause Localization for Complex Multi-Hop Agent Failures", "Một Agent giải toán 7 bước đưa ra kết quả cuối cùng sai ở bước 7 do nhận dữ liệu ảo giác từ bước 2. Thuật toán chẩn đoán tự động (Automated Fault Localization) nào xác định chính xác bước 2 là nguồn gốc gây lỗi?",
         ["Đổ lỗi hoàn toàn cho bước 7 vì nó ở cuối cùng", "Thuật toán Phân tích Nhân quả Ngược trên Cây Trace (Backward Causal Trace Analysis with Step-level Consistency Verification): Chạy mô hình NLI Verifier kiểm tra tính hợp lệ logic của từng cặp (Observation_i -> Thought_{i+1}) từ bước 1 đến bước 7; bước đầu tiên xuất hiện sự đứt gãy tính trung thực (Faithfulness Breakpoint) được gắn nhãn là Root Cause of Failure", "Chọn ngẫu nhiên một bước để sửa", "Bắt người dùng tự tìm lỗi"], 1,
         "Phân tích ngược tính nhất quán logic trên từng bước của cây Trace cho phép tự động định vị chính xác mắt xích đầu tiên bị trôi lệch trong chuỗi hành động của Agent.", "Day 13 - Slide: Causal Fault Localization in Multi-Step Agents"),
        ("High-Throughput Telemetry Pipeline with Zero Application Overhead", "Làm thế nào để ứng dụng FastAPI phục vụ 20,000 QPS có thể phát ra hàng nghìn Metrics và Traces chi tiết mà không làm tăng độ trễ (Zero Latency Overhead) của luồng xử lý chính?",
         ["Tắt hoàn toàn tính năng ghi log", "Sử dụng Cơ chế Ghi đệm Phi Khóa Bất đồng bộ (Non-blocking Ring Buffer / Lock-free Memory Queue) trong tiến trình: Ứng dụng chỉ đẩy sự kiện vào Ring Buffer trong vài micro-giây; một tiến trình nền riêng biệt (Background Daemon Thread / Sidecar Process) gom cụm và gửi dữ liệu qua gRPC sang OTel Collector theo chu kỳ", "Bắt mỗi request phải chờ gửi trace xong mới được trả lời", "Ghi trace trực tiếp vào đĩa cứng trong luồng chính"], 1,
         "Lock-free Ring Buffer và Sidecar Exporter triệt tiêu hoàn toàn chi phí chờ mạng I/O của luồng phục vụ chính, đảm bảo ứng dụng đạt thông lượng tối đa.", "Day 13 - Slide: High-Throughput Lock-Free Telemetry Architecture"),
        ("Dynamic Privacy-Preserving Telemetry with Anonymization Sandboxes", "Khi ghi lại các cuộc hội thoại trong lĩnh vực tài chính, làm thế nào để đảm bảo hệ thống Tracing lưu trữ được đầy đủ cấu trúc câu phục vụ debug nhưng triệt tiêu 100% nguy cơ lộ số thẻ tín dụng và tên khách hàng?",
         ["Chỉ lưu chuỗi rỗng", "Triển khai Tầng Xử lý Trung gian trong OTel Collector (In-flight Privacy Scrubbing Processor): Tự động phát hiện các mẫu nhạy cảm bằng mô hình NER chạy tại Collector, mã hóa một chiều các giá trị PII thành Deterministic Hashes (cho phép so khớp tần suất nhưng không thể đọc được nội dung gốc) trước khi đẩy vào kho lưu trữ", "Để dữ liệu nguyên bản vì hệ thống nội bộ đã an toàn", "Chỉ xóa số điện thoại và giữ lại số thẻ"], 1,
         "Xử lý làm sạch PII ngay tại tầng trung gian Collector ngăn chặn dữ liệu nhạy cảm chạm vào bất kỳ cơ sở dữ liệu giám sát nào ở dạng văn bản thuần.", "Day 13 - Slide: In-flight Privacy Scrubbing Processors"),
        ("Cost vs Latency vs Quality Pareto Frontier Observability", "Làm thế nào để xây dựng một Dashboard Tối ưu hóa Toàn diện theo dõi 'Đường biên Pareto' (Pareto Frontier) của hệ thống AI theo thời gian thực?",
         ["Vẽ 3 biểu đồ riêng biệt không liên quan", "Xây dựng Biểu đồ Phân tán 3 Chiều (3D Scatter / Joint Efficiency Surface): Trục X là Độ trễ (p95 Latency), Trục Y là Chi phí trung bình (Cost per Query), Trục Z là Điểm chất lượng (RAGAS/Eval Score); tự động phát hiện các phiên bản Prompt/Model nằm ngoài đường biên tối ưu Pareto để cảnh báo lãng phí tài nguyên", "Chỉ theo dõi chỉ số chi phí và bỏ qua chất lượng", "Không cần xây dựng biểu đồ"], 1,
         "Joint Efficiency Surfaces cung cấp cái nhìn đa chiều tổng thể, giúp đội ngũ quản lý đưa ra quyết định đánh đổi sáng suốt giữa chi phí, tốc độ và chất lượng phục vụ.", "Day 13 - Slide: Pareto Frontier Observability for AI Systems"),
        ("Automated Canary Evaluation with Real-time Statistical Degradation Gates", "Khi phát hành một phiên bản Prompt mới qua hình thức Canary Deploy (10% traffic), hệ thống giám sát tự động hủy bỏ phát hành (Automated Rollback) dựa trên kiểm định thống kê nào?",
         ["Chờ sau 1 tháng rồi xem báo cáo", "Chạy Kiểm định T-test / Mann-Whitney U Test liên tục trên luồng Metrics của nhóm Canary vs nhóm Control: Nếu sau 1,000 requests mà Tỉ lệ người dùng phản hồi tiêu cực tăng có ý nghĩa thống kê ($p < 0.01$) hoặc p95 TTFT tăng > 20%, hệ thống tự động ngắt Canary và chuyển 100% traffic về phiên bản an toàn", "Bắt người dùng tự bình chọn", "Tự động xóa phiên bản cũ ngay lập tức"], 1,
         "Kiểm định thống kê tự động thời gian thực ngăn chặn việc phổ biến các phiên bản có lỗi ngầm ra toàn bộ người dùng, tự động rollback trong vài phút mà không cần can thiệp thủ công.", "Day 13 - Slide: Statistical Canary Release Gates"),
        ("Observability under Extreme Network Partitions and Offline Queuing", "Khi máy chủ AI đặt tại trạm y tế vùng sâu vùng xa bị mất kết nối internet trong 12 giờ, thiết kế Tầng Đệm Giám sát Cục bộ (Local Resilient Spooling) nào đảm bảo không mất mát dữ liệu Telemetry?",
         ["Bỏ qua không ghi dữ liệu trong thời gian mất mạng", "Sử dụng Cơ chế Ghi đĩa Cục bộ có Giới hạn (Persistent Disk Spooling / Embedded RocksDB in OTel Collector): Toàn bộ traces và logs được ghi tạm thời vào cơ sở dữ liệu nhúng trên SSD; khi kết nối mạng phục hồi, Collector tự động kích hoạt tiến trình Backfill nạp bù dữ liệu theo thứ tự thời gian kèm cờ đánh dấu `delayed_telemetry`", "Tắt toàn bộ hệ thống y tế cho đến khi có mạng", "Tự động xóa dữ liệu cũ sau 5 phút"], 1,
         "Persistent Disk Spooling đảm bảo tính toàn vẹn và không mất mát dữ liệu giám sát ngay cả trong các môi trường hạ tầng mạng không ổn định.", "Day 13 - Slide: Resilient Offline Telemetry Spooling"),
        ("SLO Budget Burn-Rate Alerting Architecture", "Tại sao phương pháp cảnh báo 'Burn-Rate Alerting' trên Ngân sách Lỗi (Error Budget) lại vượt trội hơn việc chỉ cảnh báo khi vi phạm ngưỡng tức thời?",
         ["Vì Burn-rate dễ phát âm hơn", "Cảnh báo tức thời thường gây ra báo động giả khi có đột biến ngắn hạn; Burn-Rate tính toán tốc độ tiêu hao ngân sách lỗi trên nhiều cửa sổ thời gian (1 giờ và 6 giờ): Kích hoạt cảnh báo khẩn cấp khi hệ thống đang trên đà làm cạn kiệt toàn bộ ngân sách lỗi của cả tháng trong vài giờ tới", "Vì ngân sách lỗi không bao giờ bị cạn", "Không có sự khác biệt nào"], 1,
         "Multi-window Burn-Rate Alerting phát hiện chính xác các sự cố nghiêm trọng đe dọa cam kết SLA dài hạn trong khi triệt tiêu hoàn toàn các báo động rác từ những dao động nhất thời.", "Day 13 - Slide: Multi-Window Error Budget Burn-Rate Alerting"),
        ("Automated Trace-to-Dataset Pipeline for Continuous Fine-Tuning", "Làm thế nào để xây dựng một Pipeline Tự động hóa biến các Trace chất lượng cao từ Production thành Dữ liệu Huấn luyện DPO (Direct Preference Optimization)?",
         ["Thuê nhân viên copy từng dòng chat trên màn hình", "Lọc các Trace có Tương tác Sửa đổi thành công (User accepted AI correction hoặc Thumbs Up sau khi tinh chỉnh) -> Trích xuất cặp (Prompt, Chosen Response, Rejected Response) -> Chạy qua Tầng Khử PII & Kiểm tra Độc hại -> Tự động nạp vào Data Lakehouse dưới dạng tập dữ liệu DPO chuẩn sẵn sàng cho Fine-tuning", "Lấy toàn bộ dữ liệu thô bao gồm cả dữ liệu lỗi", "Bán dữ liệu cho bên thứ ba"], 1,
         "Quy trình tự động chuyển hóa Trace thành Dataset tạo ra một bánh đà tự cải tiến liên tục (Continuous Improvement Flywheel), nâng cao năng lực mô hình từ dữ liệu vận hành thực tế.", "Day 13 - Slide: Automated Trace-to-DPO Dataset Pipelines"),
        ("Security Observability: Prompt Extraction Attack Signature Profiling", "Làm thế nào để hệ thống Security Observability tự động phát hiện một chiến dịch tấn công 'Trích xuất System Prompt' phân tán từ hàng trăm địa chỉ IP khác nhau?",
         ["Chỉ kiểm tra từng địa chỉ IP riêng lẻ", "Phân tích Tương quan Cụm Ngữ nghĩa Đa Nguồn (Cross-IP Semantic Clustering): Sử dụng mô hình Clustering trên các câu hỏi từ các IP khác nhau trong vòng 1 giờ; nếu phát hiện một cụm dày đặc các câu hỏi có cùng cấu trúc khai thác (Embedding Similarity > 0.92) dù từ nhiều IP khác nhau, gắn cờ Distributed Attack và kích hoạt WAF khóa dải IP", "Khóa toàn bộ người dùng đang truy cập", "Tắt toàn bộ hệ thống máy chủ"], 1,
         "Phân tích cụm ngữ nghĩa đa nguồn phát hiện các chiến dịch tấn công phân tán tinh vi mà các hệ thống tường lửa truyền thống dựa trên IP đơn lẻ hoàn toàn bất lực.", "Day 13 - Slide: Cross-IP Semantic Attack Signature Profiling")
    ]
