    d14_med = [
        ("Biases in LLM-as-a-Judge: Position Bias", "Hiện tượng 'Position Bias' (Thiên lệch Vị trí) khi dùng LLM để so sánh 2 câu trả lời A và B biểu hiện như thế nào và cách khắc phục?",
         ["Mô hình bị nghiêng về phía bên trái màn hình", "LLM có xu hướng ưu tiên chọn câu trả lời xuất hiện ở Vị trí Đầu tiên (hoặc Vị trí Thứ hai) bất kể chất lượng thực tế; khắc phục bằng cách hoán đổi vị trí (Swap Positions A-B) và chấm điểm 2 lần độc lập", "Mô hình từ chối chấm điểm", "Không thể khắc phục được"], 1,
         "Position Bias là sai lệch cố hữu của LLM; kỹ thuật hoán đổi vị trí và lấy trung bình (Position Swapping) giúp triệt tiêu hoàn toàn thiên lệch này.", "Day 14 - Slide: LLM Judge Biases: Position Bias"),
        ("Biases in LLM-as-a-Judge: Verbosity Bias", "Hiện tượng 'Verbosity Bias' (Thiên lệch Dài dòng) của LLM Giám khảo là gì và biện pháp kiểm soát?",
         ["Mô hình chỉ thích các câu trả lời 1 chữ", "LLM có xu hướng chấm điểm cao hơn cho các câu trả lời dài, viết hoa mỹ và có định dạng phức tạp dù nội dung rỗng tuếch hoặc có lỗi; kiểm soát bằng cách đưa tiêu chí 'Tính súc tích và chính xác' (Conciseness & Precision) vào Rubric chấm điểm", "Mô hình tự động cắt ngắn câu trả lời", "Tắt tính năng chấm điểm"], 1,
         "Verbosity Bias khiến các câu trả lời lan man được ưu ái; cần định nghĩa rõ ràng trong Rubric rằng việc viết dài thừa thãi sẽ bị trừ điểm.", "Day 14 - Slide: Verbosity & Length Biases"),
        ("Biases in LLM-as-a-Judge: Self-Enhancement Bias", "Hiện tượng 'Self-Enhancement Bias' (Thiên vị Bản thân) xảy ra khi nào?",
         ["Khi mô hình tự khen ngợi lập trình viên", "Khi dùng GPT-4o làm giám khảo chấm điểm, nó có xu hướng vô thức chấm điểm cao hơn cho các câu trả lời do chính dòng họ GPT sinh ra so với các mô hình khác (như Claude hay Gemini)", "Khi mô hình tự nâng cấp phiên bản", "Khi mô hình yêu cầu tăng lương"], 1,
         "Self-Enhancement Bias là xu hướng thiên vị phong cách hành văn của chính dòng mô hình đó; cần sử dụng Hội đồng Giám khảo Đa dạng (Multi-LLM Panel) để trung hòa.", "Day 14 - Slide: Self-Enhancement & Model Family Bias"),
        ("Pairwise Comparison vs Direct Scoring", "Ưu điểm kỹ thuật vượt trội của phương pháp 'Pairwise Comparison' (So sánh từng cặp A vs B) so với 'Direct Absolute Scoring' (Chấm điểm trực tiếp 1-10) là gì?",
         ["Pairwise comparison không cần dùng máy tính", "Con người và LLM so sánh tương đối giữa 2 phương án (cái nào tốt hơn) chính xác và nhất quán hơn nhiều so với việc gán một con số tuyệt đối (Score Calibration Problem) trên thang điểm 10", "Direct scoring chạy chậm hơn 100 lần", "Không có sự khác biệt nào"], 1,
         "So sánh cặp đôi loại bỏ sự mơ hồ của thang điểm số tuyệt đối, cung cấp dữ liệu xếp hạng (Elo Rating) có độ tin cậy vượt trội.", "Day 14 - Slide: Pairwise Comparison vs Absolute Scoring"),
        ("Elo Rating System for LLMs", "Hệ thống Bảng xếp hạng Elo (tương tự như Chatbot Arena / LMSYS) xếp hạng các mô hình dựa trên nguyên lý nào?",
         ["Dựa trên số lượng tham số của mô hình", "Tính toán điểm Elo động dựa trên kết quả của hàng trăm nghìn trận đấu đối đầu ẩn danh (Blind Head-to-Head Matches) giữa các cặp mô hình do người dùng bình chọn", "Dựa trên giá tiền của card đồ họa", "Dựa trên ngày thành lập công ty"], 1,
         "LMSYS Chatbot Arena sử dụng hệ thống điểm Elo từ môn cờ vua để xây dựng bảng xếp hạng năng lực mô hình khách quan nhất thế giới.", "Day 14 - Slide: LMSYS Elo Rating System"),
        ("Pass@k Metric in Code Generation", "Công thức tính chỉ số $pass@k$ (ví dụ: $pass@1$, $pass@10$) trong đánh giá sinh mã nguồn có ý nghĩa gì?",
         ["Số lượng bài toán giải được trong k giây", "Xác suất để có ít nhất một trong số $k$ mẫu code được sinh ra vượt qua toàn bộ các bài Unit Tests kiểm thử chức năng", "Số lượng dòng code được viết bởi k lập trình viên", "Tỉ lệ phần trăm code không có lỗi chính tả"], 1,
         "Chỉ số $pass@k$ đo lường khả năng sinh ra giải pháp đúng khi cho phép mô hình thử nghiệm $k$ lần độc lập.", "Day 14 - Slide: Pass@k Metric Mathematics"),
        ("CI/CD Evaluation Gates", "Trong quy trình CI/CD cho AI, một 'Evaluation Gate' tự động chặn việc Merge code (Block Pull Request) khi phát hiện điều kiện nào?",
         ["Khi kích thước file README thay đổi", "Khi điểm số tổng hợp trên Golden Dataset (ví dụ: RAGAS Faithfulness hoặc Task Pass Rate) của nhánh mới bị giảm sút so với nhánh main (Regression Detected)", "Khi trời mưa", "Khi lập trình viên commit code vào ban đêm"], 1,
         "Evaluation Gates bảo vệ chất lượng sản phẩm trên Production bằng cách ngăn chặn tự động mọi sự suy thoái hiệu năng trước khi code được triển khai.", "Day 14 - Slide: CI/CD Quality Gates for LLMs"),
        ("Rubric Design for LLM-as-a-Judge", "Một bản Tiêu chuẩn Đánh giá (Rubric) chi tiết cho LLM Giám khảo cần bao gồm những thành phần nào để đạt độ nhất quán cao nhất?",
         ["Chỉ cần ghi 'Hãy chấm điểm thật công tâm'", "1. Định nghĩa rõ ràng mục tiêu đánh giá; 2. Thang điểm cụ thể từ 1 đến 5 kèm theo mô tả hành vi chi tiết cho TỪNG mức điểm; 3. Các ví dụ minh họa mẫu (Few-shot Rubric Examples) cho điểm 1, điểm 3 và điểm 5", "Danh sách nhân viên công ty", "Bảng mã màu RGB"], 1,
         "Rubric có cấu trúc chặt chẽ với mô tả hành vi định lượng và ví dụ minh họa giúp triệt tiêu sự mơ hồ và nâng cao độ nhất quán của LLM Giám khảo.", "Day 14 - Slide: Rubric Engineering for LLM Judges"),
        ("Synthetic Testset Complexity Evolution", "Trong RAGAS, kỹ thuật 'Complexity Evolution' nâng cao độ khó của tập dữ liệu kiểm thử nhân tạo bằng các phương pháp nào?",
         ["Viết hoa toàn bộ câu hỏi", "Biến đổi câu hỏi đơn giản ban đầu thành: Câu hỏi suy luận nhiều bước (Reasoning), Câu hỏi có điều kiện phức tạp (Conditioning), và Câu hỏi tổng hợp từ nhiều đoạn văn bản khác nhau (Multi-context)", "Dịch câu hỏi sang 5 ngôn ngữ khác nhau", "Xóa các từ có ít hơn 4 ký tự"], 1,
         "Tiến hóa độ phức tạp đảm bảo bộ dữ liệu kiểm thử bao phủ toàn diện các kịch bản khó và phức tạp mà người dùng thực tế sẽ gặp phải.", "Day 14 - Slide: Testset Evolution Strategies in RAGAS"),
        ("Multi-Judge Panel Architecture", "Mô hình 'Hội đồng Giám khảo Đa dạng' (Multi-Judge Panel / Panel of LLM Judges) giải quyết vấn đề thiên lệch mô hình bằng cách nào?",
         ["Mời 100 người dùng bình chọn", "Sử dụng đồng thời 3 mô hình từ các nhà cung cấp khác nhau (GPT-4o, Claude 3.5 Sonnet, Gemini 1.5 Pro) cùng chấm điểm độc lập trên cùng 1 Rubric, sau đó tính trung bình hoặc lấy biểu quyết đa số (Majority Consensus)", "Chỉ sử dụng mô hình nhỏ nhất", "Tắt toàn bộ hệ thống đánh giá"], 1,
         "Hội đồng giám khảo đa kiến trúc triệt tiêu các sai lệch mang tính hệ thống của từng dòng mô hình, mang lại kết quả thẩm định khách quan nhất.", "Day 14 - Slide: Multi-Judge Panels & Consensus"),
        ("Cost and Speed of Evaluation Pipelines", "Khi chạy bộ kiểm thử 5,000 cases trên mỗi Pull Request, kỹ thuật nào giúp giảm 90% chi phí và thời gian chạy Eval?",
         ["Chỉ chạy đúng 1 case duy nhất", "Áp dụng 'Tiered Eval Strategy': Chạy 50 Smoke Test cases nhanh trong PR; Sử dụng Mô hình Đánh giá Nhỏ (Fine-tuned Small Judge / SLM như Prometheus hoặc Llama-3-8B Judge) chạy song song trên GPU nội bộ thay vì gọi API thương mại đắt tiền", "Bỏ qua không kiểm thử", "Thuê nhân sự chấm điểm thủ công"], 1,
         "Sử dụng Judge SLMs chuyên dụng và phân tầng bộ kiểm thử giúp tối ưu hóa chi phí và duy trì tốc độ phát triển nhanh cho đội ngũ kỹ sư.", "Day 14 - Slide: Cost & Speed Optimization in Eval Pipelines"),
        ("Unit Tests vs End-to-End Evaluation", "Trong kiến trúc phân tầng kiểm thử AI, sự khác biệt giữa 'Component Unit Tests' và 'End-to-End Evals' là gì?",
         ["Không có sự khác biệt nào", "Unit Tests kiểm tra độc lập từng thành phần (ví dụ: Tool Execution đúng schema, Retriever trả về đúng chunk ID); End-to-End Evals đánh giá chất lượng trải nghiệm tổng thể từ góc nhìn người dùng cuối trên toàn bộ chuỗi hệ thống", "Unit tests chỉ chạy trên máy in", "End-to-end evals không dùng dữ liệu"], 1,
         "Kiểm thử đơn vị cô lập lỗi ở cấp độ hàm; kiểm thử đầu-cuối đo lường năng lực giải quyết vấn đề thực tế của toàn bộ hệ thống phối hợp.", "Day 14 - Slide: Unit Testing vs End-to-End Evaluation"),
        ("Golden Dataset Contamination (Data Leakage)", "Hiện tượng 'Data Contamination' (Nhiễm bẩn tập dữ liệu đánh giá) xảy ra khi nào và hậu quả là gì?",
         ["Khi đổ nước vào ổ cứng", "Tập dữ liệu kiểm thử (Golden Dataset) bị rò rỉ vào tập dữ liệu tiền huấn luyện hoặc dữ liệu fine-tuning của mô hình, khiến điểm benchmark cao giả tạo (Mô hình học vẹt đáp án) nhưng thất bại khi gặp dữ liệu thực tế", "Khi máy tính bị nhiễm virus", "Khi file dữ liệu bị đổi tên"], 1,
         "Nhiễm bẩn dữ liệu tạo ra ảo tưởng về năng lực mô hình; cần duy trì các tập kiểm thử bảo mật (Canary Datasets) chưa từng công khai trên internet.", "Day 14 - Slide: Benchmark Contamination & Overfitting"),
        ("Confidence Calibration Error (ECE)", "Chỉ số ECE (Expected Calibration Error) trong đánh giá mô hình phân loại của AI đo lường điều gì?",
         ["Độ dài của câu trả lời", "Mức độ chênh lệch giữa Xác suất Tự tin (Confidence Probability do mô hình ước lượng) và Độ chính xác Thực tế (Actual Accuracy), kiểm tra xem mô hình có bị tự tin thái quá khi trả lời sai hay không", "Tốc độ kết nối mạng", "Số lượng từ vựng tiếng Anh"], 1,
         "Mô hình được hiệu chuẩn tốt (Well-calibrated) là khi nó tự tin 90% thì xác suất trả lời đúng thực tế cũng phải đạt xấp xỉ 90%.", "Day 14 - Slide: Confidence Calibration & ECE Metric"),
        ("Human-in-the-loop Benchmark Calibration", "Quy trình 'Judge Calibration with Human Experts' (Hiệu chuẩn Giám khảo LLM với Chuyên gia Con người) được thực hiện như thế nào?",
         ["Con người làm theo mọi quyết định của AI", "Lấy mẫu 200 cases được chuyên gia con người chấm điểm chuẩn mực; cho LLM Judge chấm điểm trên cùng tập này; đo lường Hệ số Tương quan (Cohen's Kappa / Spearman Correlation); liên tục tinh chỉnh Rubric cho đến khi độ tương quan đạt > 0.85", "Tắt toàn bộ hệ thống AI", "Chỉ chọn các trường hợp dễ nhất"], 1,
         "Hiệu chuẩn Rubric với đánh giá chuyên gia đảm bảo LLM Giám khảo phản ánh trung thực và nhất quán các tiêu chuẩn chất lượng của con người.", "Day 14 - Slide: Human-Judge Agreement & Calibration"),
        ("Evaluation of Agentic Workflows", "Để đánh giá một Multi-Step Agent giải quyết tác vụ phức tạp, các metric nào phản ánh chất lượng toàn diện hơn chỉ số đúng/sai cuối cùng?",
         ["Màu sắc của giao diện", "1. Step Efficiency (Số bước tối ưu để hoàn thành task), 2. Tool Selection Accuracy (Tỉ lệ chọn đúng công cụ), 3. Error Recovery Rate (Khả năng tự sửa sai khi tool lỗi), 4. Token & Financial Cost per Task", "Độ dài bàn phím", "Tốc độ quạt máy chủ"], 1,
         "Đánh giá Agent đòi hỏi đo lường cả chất lượng của quỹ đạo hành động (Trajectory Quality) và hiệu quả sử dụng tài nguyên chứ không chỉ nhìn vào kết quả cuối cùng.", "Day 14 - Slide: Agent Trajectory & Multi-Step Evaluation"),
        ("Negative Testing & Safety Evals", "Tập kiểm thử 'Negative Test Cases' (Kiểm thử Phủ định) trong bộ Eval AI được thiết kế nhằm mục đích gì?",
         ["Để làm cho hệ thống bị hỏng", "Đưa ra các câu hỏi bẫy, thông tin sai sự thật, hoặc yêu cầu độc hại/ngoài phạm vi để kiểm tra xem hệ thống có biết từ chối một cách an toàn và chính xác (Correct Refusal) hay không", "Để kiểm tra tốc độ chuột", "Để tăng dung lượng ổ cứng"], 1,
         "Kiểm thử phủ định đảm bảo hệ thống không chỉ biết trả lời câu hỏi đúng mà còn phải biết từ chối an toàn trước các truy vấn phi pháp hoặc bẫy lừa.", "Day 14 - Slide: Negative Testing & Safety Evaluations"),
        ("Continuous Evaluation Flywheel", "Khái niệm 'Continuous Evaluation Flywheel' (Bánh đà Đánh giá Liên tục) trong vận hành AI Production là gì?",
         ["Một loại bánh xe thực tế trong phòng máy chủ", "Quy trình tự động: Lấy mẫu traffic thực tế -> Chạy Eval tự động phát hiện các ca thất bại (Edge Cases) -> Bổ sung ca khó vào Golden Dataset -> Tinh chỉnh Prompt/Mô hình -> Chạy Regression Test và Deploy bản cải tiến", "Quy trình xóa dữ liệu mỗi tuần", "Quy trình in báo cáo tài chính"], 1,
         "Bánh đà đánh giá liên tục biến các thất bại trên Production thành nguồn dữ liệu quý giá giúp sản phẩm ngày càng trở nên thông minh và bền bỉ hơn.", "Day 14 - Slide: Continuous Evaluation Flywheel Architecture")
    ]

    d14_hard = [
        ("Enterprise-Grade Automated Eval Pipeline with LLM Judges", "Thiết kế một Hạ tầng Đánh giá Tự động hóa Toàn diện (Continuous Evaluation & Benchmarking Infrastructure) phục vụ 50 AI Agents trong hệ thống CI/CD của một tập đoàn tài chính. Kiến trúc nào sau đây đảm bảo tính khoa học, khách quan, không thiên lệch và tối ưu chi phí?",
         ["Chỉ nhờ 1 nhân viên thực tập kiểm tra ngẫu nhiên 5 câu hỏi trước khi deploy", "Triển khai Kiến trúc Đánh giá Phân tầng 4 Cấp độ: 1. Deterministic Assertion Gates (Kiểm tra Schema, PII, Latency, Keyword Bounds bằng DeepEval); 2. Panel of Judges độc lập (GPT-4o + Claude 3.5 Sonnet) chạy trên Structured Rubrics với kỹ thuật Hoán đổi Vị trí (Position Swapping) và Majority Voting; 3. Specialized Fact-Checking Verifier (NLI Entailment Engine trên GPU cục bộ đo lường Faithfulness); 4. Tự động tích hợp GitHub Actions chặn PR nếu có bất kỳ tiêu chí nào bị hồi quy (Regression Gate)", "Tắt toàn bộ hệ thống kiểm thử tự động để đẩy nhanh tiến độ", "Chỉ chạy kiểm thử sau khi khách hàng báo lỗi trên mạng xã hội"], 1,
         "Kiến trúc đánh giá phân tầng kết hợp giữa quy tắc tất định, hội đồng giám khảo đa dạng và kiểm chứng NLI cục bộ cung cấp bức tường bảo vệ chất lượng vững chắc nhất cho doanh nghiệp.", "Day 14 - Slide: Enterprise AI Evaluation Architecture"),
        ("Formulating Unbiased Mathematical Rubrics for G-Eval", "Khi thiết kế một hàm đánh giá chất lượng tóm tắt văn bản y khoa bằng G-Eval, phương pháp toán học nào loại bỏ hoàn toàn sự không ổn định (Instability) của điểm số lấy mẫu ngẫu nhiên?",
         ["Chỉ lấy mẫu 1 lần với temperature = 1.5", "Sử dụng Cơ chế Tính Điểm Kỳ vọng qua Phân phối Logits (Expectation over Probabilities): Trích xuất log-probabilities của các token điểm số $s \\in \\{1, 2, 3, 4, 5\\}$ từ phản hồi của LLM Judge, tính toán $Score = \\sum_{i=1}^5 i \\cdot P(\\text{score}=i)$, cho ra điểm số thực liên tục có độ lệch chuẩn $\\sigma \\to 0$ qua các lần chạy", "Làm tròn tất cả điểm số về 0", "Chọn ngẫu nhiên một con số"], 1,
         "Tính điểm kỳ vọng qua phân phối xác suất logits triệt tiêu hoàn toàn tính ngẫu nhiên của bước lấy mẫu, mang lại điểm số đánh giá tất định và có độ mịn toán học cao.", "Day 14 - Slide: Mathematical Formulation of G-Eval Logit Expectation"),
        ("Fine-Tuning Specialized Open-Source Judge Models (Judge SLMs)", "Một doanh nghiệp muốn chạy 1 triệu lượt đánh giá chất lượng mỗi ngày mà không muốn chi trả hàng triệu USD cho API của OpenAI. Chiến lược Huấn luyện Mô hình Giám khảo Chuyên dụng (Custom Judge SLM) nào đạt hiệu quả tối ưu?",
         ["Dùng mô hình BERT đời cũ không qua huấn luyện", "Quy trình Chưng cất Giám khảo (Judge Distillation): Thu thập 50,000 mẫu đánh giá chất lượng cao từ Hội đồng Frontier LLMs + Chuyên gia con người -> Huấn luyện mô hình mã nguồn mở nhỏ (như Llama-3-8B hoặc Qwen-2.5-7B) bằng Direct Preference Optimization (DPO) với hàm mất mát chuyên biệt cho tác vụ phê bình (Critic Loss) -> Triển khai trên cụm vLLM nội bộ với độ trễ < 50ms và chi phí $0", "Thuê 10,000 sinh viên ngồi chấm điểm thủ công", "Không cần đánh giá nữa"], 1,
         "Chưng cất năng lực đánh giá sang các mô hình nhỏ chuyên dụng (Judge SLMs) giúp doanh nghiệp tự chủ hoàn toàn hạ tầng đánh giá quy mô lớn với chi phí vận hành cực thấp.", "Day 14 - Slide: Distilling and Fine-Tuning Open-Source Judge Models"),
        ("Multi-Agent Trajectory Evaluation with Graph Alignment", "Khi đánh giá một hệ thống Multi-Agent phức tạp thực hiện 15 bước gọi công cụ phối hợp, phương pháp 'Graph Alignment & Causal Trajectory Scoring' đo lường chất lượng luồng thực thi như thế nào?",
         ["Chỉ kiểm tra xem chương trình có chạy hết không", "Mô hình hóa toàn bộ chuỗi hành động thực tế thành một Đồ thị Nhân quả (Actual Trajectory DAG) và so khớp hình học với Đồ thị Tối ưu Chuẩn (Optimal Reference Graph): Tính toán Graph Edit Distance (GED), Tỉ lệ hành động thừa thãi (Redundant Step Ratio), và Điểm hiệu quả phục hồi lỗi (Fault Recovery Efficiency Score)", "Đếm số lượng chữ cái trong file log", "Tự động cho điểm tối đa nếu Agent không bị crash"], 1,
         "Đánh giá đồ thị quỹ đạo đo lường độ chính xác và tính tối ưu của toàn bộ quá trình lập luận và điều phối công cụ, phát hiện các bước đi luẩn quẩn hoặc lãng phí tài nguyên.", "Day 14 - Slide: Graph-based Multi-Agent Trajectory Evaluation"),
        ("Automated Adversarial Eval Suite Generation with Evol-Instruct", "Làm thế nào để xây dựng một Bộ sinh Testset Tự động có khả năng liên tục 'Tìm diệt' các điểm yếu và góc khuất (Blind Spots) của hệ thống RAG doanh nghiệp?",
         ["Tải các câu đố vui trên mạng về kiểm tra", "Xây dựng Red-Teaming Evol-Agent Pipeline: Sử dụng LLM phân tích cấu trúc kho dữ liệu -> Tự động sinh ra các câu hỏi đòi hỏi thông tin nằm ở ranh giới giữa 2 tài liệu (Multi-hop Boundary Cases) -> Tinh chỉnh câu hỏi bằng các kỹ thuật ngụy biện ngữ nghĩa, câu hỏi phủ định giả (False Premise), và chèn các yếu tố gây nhiễu (Distractor Injection) để kiểm thử sức chịu đựng của RAG", "Copy lại các câu hỏi cũ của người dùng", "Chỉ tạo ra các câu hỏi đơn giản"], 1,
         "Quy trình tự động hóa tiến hóa đối kháng tạo ra các bài kiểm thử chất lượng cao, chủ động bộc lộ các điểm mù tri thức của hệ thống trước khi triển khai thực tế.", "Day 14 - Slide: Adversarial Testset Generation with Evol-Instruct"),
        ("Confidence vs Accuracy Calibration Curve Optimization", "Trong các ứng dụng pháp lý và y tế, làm thế nào để xây dựng đường cong hiệu chuẩn (Calibration Curve) biến đổi điểm số tự tin thô của mô hình thành Xác suất Tin cậy Thực tế (Calibrated Probabilities)?",
         ["Nhân điểm số với 100", "Áp dụng kỹ thuật Isotonic Regression hoặc Temperature Scaling trên tập dữ liệu kiểm định độc lập (Validation Set): Tìm tham số nhiệt độ tối ưu $T^*$ để cực tiểu hóa sai số Expected Calibration Error (ECE), đảm bảo khi hệ thống báo độ tự tin 95% thì xác suất đúng thực tế đạt chính xác 0.95", "Làm tròn tất cả điểm số về số nguyên", "Bỏ qua không cần hiệu chuẩn"], 1,
         "Temperature Scaling và Isotonic Regression là các công cụ chuẩn mực hiệu chuẩn phân phối xác suất, giúp hệ thống đưa ra các ước lượng độ tự tin trung thực và đáng tin cậy.", "Day 14 - Slide: Temperature Scaling & Probability Calibration"),
        ("Contamination-Proof Evaluation with Dynamic Canary Token Injection", "Làm thế nào để phát hiện xem một bộ Benchmark công khai có bị 'Nhiễm bẩn' (Data Contamination) vào dữ liệu huấn luyện của một mô hình thương mại kín (Closed-source LLM) hay không?",
         ["Hỏi trực tiếp công ty phát triển mô hình", "Kỹ thuật 'Canary Token & Perplexity Discontinuity Analysis': Chèn các chuỗi khóa bí mật duy nhất (Canary Hashes) ẩn giấu trong tập dữ liệu kiểm thử; nếu mô hình có thể tự động hoàn thành chuỗi hash bí mật này với Perplexity cực thấp, chứng minh chắc chắn tập dữ liệu đã bị rò rỉ vào tập pre-training của mô hình đó", "Kiểm tra xem mô hình có trả lời nhanh không", "Không thể phát hiện được"], 1,
         "Phân tích Perplexity trên các chuỗi khóa Canary Token là phương pháp khoa học chuẩn xác để vạch trần hiện tượng nhiễm bẩn dữ liệu trong các mô hình hộp đen.", "Day 14 - Slide: Detecting Benchmark Contamination via Canary Probes"),
        ("Statistical Significance Testing in AI A/B Evals", "Khi so sánh Prompt Mới và Prompt Cũ trên 2,000 mẫu kiểm thử, điểm trung bình của Prompt Mới tăng từ 82.1% lên 83.4%. Phép kiểm định thống kê nào xác nhận cải tiến này là thực chất chứ không phải ngẫu nhiên?",
         ["Khẳng định ngay là Prompt Mới tốt hơn vì 83.4 > 82.1", "Áp dụng Kiểm định McNemar Test (cho dữ liệu phân loại nhị phân Pass/Fail) hoặc Wilcoxon Signed-Rank Test (cho dữ liệu điểm số liên tục): Chỉ chấp nhận kết luận cải tiến khi Giá trị $p < 0.01$ (Bác bỏ giả thuyết vô hiệu $H_0$ với độ tin cậy 99%)", "Lấy điểm trung bình cộng chia đôi", "Bình chọn bằng tay"], 1,
         "Kiểm định thống kê suy luận (Inferential Statistics) là yêu cầu bắt buộc để chứng minh các cải tiến kỹ thuật trong AI mang tính thực chất và bền vững.", "Day 14 - Slide: Rigorous Statistical Significance Testing for LLMs"),
        ("Human-in-the-Loop Inter-Annotator Agreement Optimization", "Khi 3 chuyên gia con người cùng gán nhãn cho bộ Golden Dataset nhưng chỉ đạt Hệ số Đồng thuận liên thẩm định (Inter-Annotator Agreement / Fleiss' Kappa) $\\kappa = 0.55$ (Mức trung bình yếu). Quy trình chuẩn hóa nào nâng độ đồng thuận lên $\\kappa > 0.85$?",
         ["Sa thải 2 chuyên gia và chỉ giữ lại 1 người", "Quy trình Tinh chỉnh Hướng dẫn Đánh giá (Annotation Guidelines Refinement & Consensus Adjudication): 1. Tổ chức buổi thảo luận mâu thuẫn (Disagreement Workshop) để phân tích các ca bất đồng; 2. Làm rõ các trường hợp mơ hồ (Edge Cases) trong tài liệu hướng dẫn; 3. Bổ sung các ví dụ ranh giới rõ ràng; 4. Tiến hành vòng gán nhãn thử nghiệm thứ hai", "Bắt các chuyên gia sao chép bài của nhau", "Bỏ qua không cần tính hệ số đồng thuận"], 1,
         "Tinh chỉnh tài liệu hướng dẫn gán nhãn dựa trên phân tích mâu thuẫn là phương pháp bài bản để chuẩn hóa nhận thức và nâng cao độ chính xác của tập dữ liệu vàng.", "Day 14 - Slide: Inter-Annotator Agreement & Fleiss Kappa Optimization"),
        ("End-to-End Metric Decomposition for Root Cause Diagnosis", "Một hệ thống RAG đạt điểm hài lòng tổng thể thấp ($F_1 = 0.62$). Công thức phân rã lỗi nào bóc tách chính xác phần trăm đóng góp của từng thành phần (Retrieval vs Generation) vào sự suy thoái chung?",
         ["Đổ lỗi 50% cho mỗi bên", "Phân rã thành tích số các xác suất độc lập: $P(\\text{Success}) = P(\\text{Retrieved Correctly}) \\times P(\\text{Generated Factually} | \\text{Retrieved Correctly}) \\times P(\\text{Format Valid} | \\text{Generated Factually})$; tính toán độ suy giảm tại từng mắt xích để xác định thành phần ưu tiên cải tiến", "Cộng tất cả các điểm số lại", "Không thể phân rã được"], 1,
         "Phân rã xác suất chuỗi lỗi giúp định lượng chính xác ROI kỹ thuật: Cải tiến tầng Retrieval hay tầng Prompt Engineering sẽ mang lại bước nhảy vọt lớn nhất cho hệ thống.", "Day 14 - Slide: Hierarchical Metric Decomposition in AI Systems"),
        ("Automated Regression Testing under Stochastic Model Upgrades", "Khi nhà cung cấp LLM cập nhật phiên bản mô hình ngầm (e.g. OpenAI cập nhật snapshot), làm thế nào để phát hiện ngay các 'Silent Failures' trên 200 tính năng nội bộ trong 15 phút?",
         ["Chờ khách hàng báo lỗi", "Xây dựng Hệ thống Kiểm thử Hồi quy Tự động Hàng đêm (Nightly Matrix Regression Runner): Tự động phát song song 5,000 Golden Test Cases qua phiên bản mô hình mới -> So khớp Assertion Logic & Semantic Similarity với Baseline -> Tạo Báo cáo Sai lệch Nhiệt (Heatmap Regression Report) kích hoạt cảnh báo đỏ nếu phát hiện gãy vỡ cục bộ", "Tắt toàn bộ hệ thống để kiểm tra thủ công", "Không cập nhật mô hình mới"], 1,
         "Hệ thống ma trận kiểm thử hồi quy tự động phát hiện ngay lập tức các hành vi thay đổi ngầm của mô hình nhà cung cấp, bảo vệ tính ổn định của toàn bộ hệ sinh thái sản phẩm.", "Day 14 - Slide: Automated Nightly Regression Testing Architecture"),
        ("Multi-Modal Evaluation Metrics: CLIPScore & VQA-Accuracy", "Khi đánh giá một Agent Đa phương thức tiếp nhận câu hỏi và hình ảnh đồ thị, hai chỉ số định lượng nào đánh giá chính xác cả năng lực thấu hiểu thị giác và tính đúng đắn của văn bản?",
         ["Chỉ đo kích thước file ảnh", "CLIPScore (Đo lường độ tương đồng ngữ nghĩa hình ảnh - văn bản trong không gian biểu diễn đa phương thức CLIP) kết hợp VQA-Accuracy (Đo lường tính chính xác của câu trả lời trên các tập dữ liệu Visual Question Answering chuẩn)", "Độ phân giải của màn hình", "Số lượng màu sắc trong biểu đồ"], 1,
         "CLIPScore và VQA-Accuracy cung cấp thước đo định lượng toàn diện cho các tác vụ suy luận kết hợp giữa dữ liệu thị giác và ngôn ngữ tự nhiên.", "Day 14 - Slide: Multi-Modal AI Evaluation Metrics")
    ]
