    # ==========================================
    # DAY 15: Production Deployment & Practical Implementation
    # ==========================================
    d15_easy = [
        ("Production Architecture", "Một kiến trúc ứng dụng AI hoàn chỉnh trong môi trường Production bao gồm những tầng cốt lõi nào?",
         ["Chỉ cần một file script Python duy nhất", "Tầng Giao diện (Frontend/UI) -> Tầng Cổng Gateway & Bảo mật -> Tầng Điều phối Logic & Orchestration (Agent/RAG) -> Tầng Lưu trữ Tri thức & Cache -> Tầng Mô hình Nền tảng (LLMs/Embeddings) -> Tầng Giám sát (Observability)", "Chỉ cần màn hình và bàn phím", "Chỉ cần tài khoản ngân hàng"], 1,
         "Kiến trúc Production phân tầng tách biệt rõ ràng giữa bảo mật, điều phối logic, lưu trữ dữ liệu và giám sát vận hành.", "Day 15 - Slide: End-to-End Enterprise AI Architecture"),
        ("Rollout Strategies: Canary", "Chiến lược triển khai 'Canary Deployment' phát hành phiên bản mới như thế nào?",
         ["Phát hành cho toàn bộ 100% người dùng ngay lập tức", "Chỉ chuyển hướng một tỉ lệ nhỏ lưu lượng (ví dụ: 5% người dùng) sang phiên bản mới để theo dõi lỗi và độ ổn định trước khi mở rộng dần lên 100%", "Chỉ phát hành cho loài chim hoàng yến", "Tắt toàn bộ hệ thống máy chủ cũ"], 1,
         "Canary Deployment giảm thiểu tối đa phạm vi ảnh hưởng (Blast Radius) nếu phiên bản mới xuất hiện lỗi nghiêm trọng.", "Day 15 - Slide: Canary Rollout Strategies"),
        ("Rollout Strategies: Blue-Green", "Chiến lược triển khai 'Blue-Green Deployment' hoạt động theo nguyên lý nào?",
         ["Sơn máy chủ màu xanh lam và màu xanh lá cây", "Duy trì song song hai môi trường giống hệt nhau: Môi trường Blue (đang chạy bản cũ phục vụ khách) và Môi trường Green (chứa bản mới đã test hoàn chỉnh); chuyển toàn bộ traffic từ Blue sang Green tức thời bằng cách đổi cổng Router", "Xóa toàn bộ dữ liệu cũ", "Tắt máy chủ vào ban ngày"], 1,
         "Blue-Green Deployment cho phép phát hành phiên bản mới không có downtime và hỗ trợ hoàn tác (Rollback) tức thời chỉ bằng 1 thao tác chuyển mạch.", "Day 15 - Slide: Blue-Green Deployment Architecture"),
        ("Rollout Strategies: Shadow Deploy", "Chiến lược triển khai 'Shadow Deployment' (Triển khai Bóng ma) có đặc điểm gì?",
         ["Chỉ chạy phần mềm vào ban đêm", "Nhân bản lưu lượng người dùng thực tế gửi đồng thời tới cả phiên bản cũ và phiên bản mới, nhưng chỉ trả kết quả từ phiên bản cũ cho người dùng, dùng kết quả bản mới để kiểm tra hiệu năng ngầm", "Tắt toàn bộ đèn trong văn phòng", "Không cho người dùng biết công ty có AI"], 1,
         "Shadow Deployment cho phép kiểm tra tải thực tế và độ chính xác của phiên bản mới trong môi trường Production mà hoàn toàn không gây rủi ro cho người dùng.", "Day 15 - Slide: Shadow & Dark Launching"),
        ("SLA / SLO / SLI", "Mối quan hệ phân cấp giữa SLI, SLO và SLA trong cam kết dịch vụ là gì?",
         ["Cả 3 từ đều viết tắt của cùng một khái niệm", "SLI (Chỉ số đo lường thực tế) -> SLO (Mục tiêu nội bộ cam kết phấn đấu) -> SLA (Cam kết pháp lý với khách hàng kèm điều khoản bồi thường tài chính nếu vi phạm)", "SLA là code, SLO là tài liệu, SLI là hình ảnh", "SLA nhỏ hơn SLI 100 lần"], 1,
         "SLI là thước đo thực tế; SLO là mục tiêu vận hành nội bộ (thường khắt khe hơn); SLA là cam kết hợp đồng pháp lý với khách hàng.", "Day 15 - Slide: SLI, SLO, and SLA Hierarchy"),
        ("Total Cost of Ownership (TCO)", "Chi phí Sở hữu Toàn diện (TCO) của một hệ thống AI Doanh nghiệp bao gồm những khoản chi phí nào?",
         ["Chỉ tính riêng tiền điện", "Chi phí gọi API mô hình + Chi phí hạ tầng đám mây (GPU/RAM/Network) + Chi phí bản quyền phần mềm + Chi phí nhân sự kỹ thuật vận hành và gán nhãn dữ liệu", "Chỉ tính tiền mua bàn ghế", "Chỉ tính tiền cà phê"], 1,
         "TCO bao quát toàn bộ chi phí tài chính, hạ tầng và nguồn nhân lực cần thiết để duy trì hệ thống AI xuyên suốt vòng đời sản phẩm.", "Day 15 - Slide: Total Cost of Ownership (TCO) in AI"),
        ("Production Security Checklist", "Hạng mục nào sau đây là BẮT BUỘC phải hoàn thành trong 'Production Security Checklist' trước khi Go-Live?",
         ["Mua đồ chơi cho văn phòng", "Mã hóa dữ liệu tại chỗ và trên đường truyền (TLS), Phân quyền truy cập tối thiểu (RBAC), Kích hoạt Guardrail lọc PII/Injection, và Lưu trữ API Keys trong Secret Manager", "In toàn bộ mã nguồn ra giấy", "Mở toàn bộ cổng mạng ra ngoài internet"], 1,
         "Security Checklist đảm bảo các tiêu chuẩn bảo mật hạ tầng và an toàn thông tin được thực thi nghiêm ngặt trước khi mở cửa cho người dùng thực tế.", "Day 15 - Slide: Pre-production Security Checklist"),
        ("Graceful Degradation Tiers", "Khi nhà cung cấp LLM chính bị sập hoàn toàn, tầng thoái lui (Fallback Tier) an toàn đầu tiên của hệ thống nên là gì?",
         ["Tắt trang web và hiển thị thông báo sập hệ thống", "Tự động chuyển hướng sang mô hình LLM dự phòng của nhà cung cấp khác (ví dụ: chuyển từ OpenAI sang Azure OpenAI hoặc Anthropic Claude)", "Xóa toàn bộ database người dùng", "Gửi email xin lỗi từng khách hàng"], 1,
         "Multi-provider Failover là phòng tuyến dự phòng đầu tiên giúp duy trì trải nghiệm AI liên tục khi một nhà cung cấp gặp sự cố.", "Day 15 - Slide: Multi-Tier Fallback Architectures"),
        ("Edge AI vs Cloud AI", "Ưu điểm lớn nhất của việc triển khai mô hình AI tại thiết bị đầu cuối (Edge AI) so với Đám mây (Cloud AI) là gì?",
         ["Edge AI luôn thông minh hơn Cloud AI", "Độ trễ phản hồi cực thấp (không phụ thuộc kết nối internet), Bảo mật dữ liệu tuyệt đối tại chỗ (Dữ liệu không rời khỏi thiết bị) và Tiết kiệm chi phí băng thông máy chủ", "Edge AI không cần pin", "Edge AI có màn hình lớn hơn"], 1,
         "Edge AI xử lý dữ liệu trực tiếp tại nguồn, mang lại sự riêng tư tối đa và khả năng hoạt động ngoại tuyến (Offline Availability).", "Day 15 - Slide: Cloud AI vs Edge AI Trade-offs"),
        ("Model Lifecycle Management", "Khi một phiên bản mô hình cũ chuẩn bị ngừng hỗ trợ (Deprecation), quy trình chuyển giao (Migration Workflow) cần bắt đầu từ bước nào?",
         ["Xóa mô hình cũ ngay lập tức", "Chạy toàn bộ bộ kiểm thử Golden Dataset trên mô hình mới để đánh giá độ tương thích, tinh chỉnh lại Prompt/Schema và kiểm tra hồi quy", "Chờ đến ngày mô hình bị tắt mới sửa code", "Tắt toàn bộ hệ thống"], 1,
         "Kiểm thử hồi quy trên tập dữ liệu chuẩn là bước khởi đầu bắt buộc để xác định các sai lệch hành vi của phiên bản mô hình mới trước khi chuyển đổi.", "Day 15 - Slide: Model Lifecycle & Deprecation Management"),
        ("Capacity Planning", "Mục tiêu của 'Capacity Planning' (Hoạch định năng lực hạ tầng) trong triển khai AI là gì?",
         ["Dự báo thời tiết", "Ước tính chính xác nhu cầu tài nguyên tính toán (Số lượng GPU, Dung lượng RAM, Băng thông mạng, Quota API token) cần thiết để đáp ứng lưu lượng người dùng dự kiến trong tương lai mà không bị quá tải", "Tính toán diện tích phòng họp", "Đếm số lượng bóng đèn trong công ty"], 1,
         "Hoạch định năng lực giúp doanh nghiệp chủ động dự trù tài nguyên phần cứng và hạn mức API, ngăn ngừa hiện tượng nghẽn mạng vào giờ cao điểm.", "Day 15 - Slide: Capacity Planning for AI Workloads"),
        ("Post-Mortem Culture", "Một buổi 'Blameless Post-Mortem' (Rút kinh nghiệm không đổ lỗi) sau sự cố Production nhằm mục đích tối thượng nào?",
         ["Xác định ai là người có lỗi để phạt tiền", "Phân tích có hệ thống nguyên nhân gốc rễ và đưa ra các hành động khắc phục cụ thể (Action Items) nhằm ngăn chặn sự cố tương tự tái diễn trong tương lai", "Giấu kín thông tin sự cố với ban giám đốc", "Xóa toàn bộ các file log"], 1,
         "Văn hóa không đổ lỗi khuyến khích sự minh bạch, giúp tổ chức học hỏi từ sai lầm và hoàn thiện độ bền vững của hệ thống.", "Day 15 - Slide: Incident Post-Mortems & Continuous Learning"),
        ("Zero-Downtime Migration", "Trong quá trình nâng cấp hệ thống AI, 'Zero-Downtime Migration' đảm bảo điều gì cho khách hàng?",
         ["Khách hàng được dùng miễn phí", "Dịch vụ liên tục hoạt động bình thường 100% thời gian, người dùng không nhận thấy bất kỳ sự gián đoạn hay mất kết nối nào trong suốt quá trình triển khai phiên bản mới", "Khách hàng phải đăng nhập lại mỗi 5 phút", "Tốc độ mạng bị chậm đi một nửa"], 1,
         "Zero-Downtime Migration duy trì tính liên tục của trải nghiệm người dùng trong mọi đợt nâng cấp mã nguồn hoặc hạ tầng.", "Day 15 - Slide: Zero-Downtime Deployment Patterns"),
        ("AI Product KPIs", "KPI nào sau đây phản ánh chính xác nhất Giá trị Nghiệp vụ (Business Value) của một Trợ lý AI Hỗ trợ Khách hàng?",
         ["Số dòng code trong file server.py", "First-Contact Resolution Rate (Tỉ lệ giải quyết dứt điểm vấn đề ngay từ lượt tương tác đầu tiên) kết hợp CSAT (Điểm hài lòng của khách hàng)", "Số lượng máy tính trong phòng làm việc", "Số lượng nhân viên tham gia dự án"], 1,
         "Chỉ số giải quyết dứt điểm vấn đề và mức độ hài lòng phản ánh trực tiếp hiệu quả kinh tế và chất lượng phục vụ thực tế của trợ lý AI.", "Day 15 - Slide: Key Business Performance Indicators"),
        ("Exam Preparation Strategy", "Khi chuẩn bị cho kỳ thi Đánh giá Năng lực Kỹ nghệ AI (Midterm/Final Exam), phương pháp ôn tập nào mang lại hiệu quả cao nhất?",
         ["Học thuộc lòng từng câu chữ không cần hiểu", "Hệ thống hóa kiến trúc theo sơ đồ tư duy (Concept Mapping), Nắm vững các Trade-offs kỹ thuật (Ưu/Nhược điểm của từng giải pháp) và Thực hành giải quyết các bài toán tình huống thực tế (Case Studies)", "Chỉ học 1 ngày đầu tiên và bỏ qua các ngày còn lại", "Không cần ôn tập"], 1,
         "Nắm vững các nguyên lý kiến trúc, phân tích trade-offs và tư duy xử lý sự cố thực tế là chìa khóa để đạt điểm số xuất sắc trong các kỳ thi kỹ nghệ AI.", "Day 15 - Slide: Comprehensive Course Wrap-up & Exam Strategy")
    ]

    d15_med = [
        ("Production Multi-Tier Fallback Architecture", "Khi thiết kế Tầng Thoái lui Đa cấp (Multi-Tier Fallback Architecture) cho hệ thống AI phục vụ 1 triệu người dùng, thứ tự chuyển mạch chuẩn mực khi xảy ra sự cố là gì?",
         ["Sập toàn bộ hệ thống ngay khi có lỗi nhỏ", "Tier 1 (Edge Semantic Cache) -> Tier 2 (Primary Frontier LLM: GPT-4o) -> Tier 3 (Secondary Fallback LLM: Claude 3.5 Sonnet / Azure OpenAI) -> Tier 4 (Fast Local SLM: vLLM Llama-3-8B) -> Tier 5 (Rule-based Static Helpful Message)", "Chuyển thẳng từ GPT-4o sang tắt server", "Không cần thiết lập các tầng dự phòng"], 1,
         "Kiến trúc thoái lui 5 tầng đảm bảo hệ thống luôn cung cấp giá trị tốt nhất có thể cho người dùng trong mọi tình huống thảm họa hạ tầng.", "Day 15 - Slide: Five-Tier Fallback Architecture"),
        ("Canary Deployment with Automated Health Checks", "Trong quá trình Canary Rollout (10% traffic), các chỉ số vi mô nào cần được hệ thống giám sát tự động theo dõi để quyết định Tiếp tục mở rộng hay Tự động Rollback?",
         ["Nhiệt độ phòng máy chủ", "Tỉ lệ lỗi HTTP 5xx (Error Rate > 0.5%), Độ trễ p95 Latency tăng đột biến (> 25%), Tỉ lệ người dùng bấm Thumbs Down tăng, và Tỉ lệ vi phạm Output Guardrail", "Số lượng file trong thư mục", "Tốc độ gõ phím của lập trình viên"], 1,
         "Giám sát tự động các chỉ số lỗi, độ trễ và phản hồi tiêu cực giúp kích hoạt rollback ngay trong vài phút nếu bản Canary có khuyết tật.", "Day 15 - Slide: Automated Canary Health Metrics"),
        ("Total Cost of Ownership Modeling for Hybrid AI", "Khi so sánh TCO giữa việc Sử dụng Hoàn toàn API Thương mại (Cloud APIs) và Tự Vận hành Cụm Mô hình Riêng (Self-Hosted on Private GPU Cluster), điểm hòa vốn (Break-even Point) thường xuất hiện khi nào?",
         ["Khi công ty có 10 nhân viên", "Khi lưu lượng vượt qua ngưỡng quy mô lớn (ví dụ: > 100 triệu tokens/ngày) với mẫu prompt cố định và ổn định trong thời gian dài, chi phí thuê cụm GPU chuyên dụng (Fixed GPU Cost) sẽ trở nên rẻ hơn chi phí biến đổi tính theo token của API thương mại", "Không bao giờ hòa vốn", "Khi giá card đồ họa bằng 0"], 1,
         "Tự host mô hình có chi phí cố định cao (Capex/Opex phần cứng) nhưng chi phí biên trên mỗi token cực thấp, trở nên tối ưu khi đạt quy mô lưu lượng khổng lồ.", "Day 15 - Slide: TCO Modeling: Cloud APIs vs Self-Hosted GPUs"),
        ("Graceful Degradation: Load Shedding Strategy", "Khi hệ thống bị quá tải 300% lưu lượng trong sự kiện Flash Sale, chiến lược 'Graceful Load Shedding' (Cắt giảm tải mềm dẻo) bảo vệ hệ thống như thế nào?",
         ["Tắt hoàn toàn website của công ty", "Tự động tắt các tính năng AI phụ trợ tốn nhiều token (như Phân tích chuyên sâu, Gợi ý mở rộng), chuyển toàn bộ luồng RAG sang chế độ tìm kiếm nhanh với Top-k nhỏ hơn, và ưu tiên băng thông xử lý giao dịch thanh toán cốt lõi", "Ngắt kết nối ngẫu nhiên của người dùng", "Bắt người dùng trả thêm tiền để được phục vụ"], 1,
         "Cắt giảm tải mềm dẻo hy sinh các tính năng phụ trợ không thiết yếu để bảo vệ luồng nghiệp vụ sống còn của doanh nghiệp trong cơn bão lưu lượng.", "Day 15 - Slide: Adaptive Load Shedding Strategies"),
        ("Feature Flags & Dynamic Prompt Configuration", "Tại sao việc sử dụng Hệ thống Cờ tính năng (Feature Flags như LaunchDarkly / Unleash) cho các Prompt và Cấu hình Mô hình lại là chuẩn mực kỹ thuật phần mềm hiện đại?",
         ["Để làm cho code dài hơn", "Cho phép kỹ sư bật/tắt tính năng AI mới, thay đổi System Prompt hoặc chuyển đổi nhà cung cấp LLM tức thời trên Production chỉ bằng việc đổi config trên Dashboard mà KHÔNG CẦN build lại Docker image hay redeploy server", "Để bắt buộc người dùng nộp phí", "Vì Python bắt buộc phải dùng Feature Flags"], 1,
         "Feature Flags tách rời việc Triển khai Mã nguồn (Deployment) khỏi việc Phát hành Tính năng (Release), cho phép kiểm soát rủi ro và thử nghiệm linh hoạt.", "Day 15 - Slide: Feature Flags for AI Configuration"),
        ("Data Lifecycle & Vector Index Compaction", "Tại sao việc định kỳ thực hiện 'Compaction & Re-indexing' trên Vector Database lại quan trọng đối với chi phí và hiệu năng dài hạn?",
         ["Để đổi tên cơ sở dữ liệu", "Loại bỏ các bản ghi đã xóa mềm (Tombstones), thu gọn không gian đĩa cứng, tái cân bằng cấu trúc đồ thị HNSW giúp duy trì độ trễ tìm kiếm thấp và giảm dung lượng RAM tiêu thụ", "Để xóa toàn bộ dữ liệu lịch sử", "Vì nhà sản xuất phần cứng yêu cầu"], 1,
         "Vector Compaction dọn dẹp các mảnh vụn dữ liệu và tối ưu hóa lại cấu trúc đồ thị tìm kiếm sau nhiều tháng vận hành thêm/xóa/sửa liên tục.", "Day 15 - Slide: Vector Database Maintenance & Compaction"),
        ("Multi-Zone High Availability (HA) Architecture", "Kiến trúc 'Multi-Availability Zone (Multi-AZ) Deployment' bảo vệ hệ thống AI khỏi loại sự cố nào?",
         ["Sự cố mất điện hoặc thảm họa phần cứng tại một Trung tâm Dữ liệu đơn lẻ (Single Data Center Outage), tự động chuyển mạch lưu lượng sang Trung tâm Dữ liệu lân cận trong cùng khu vực mà không làm gián đoạn dịch vụ", "Sự cố mất kết nối mạng toàn cầu", "Sự cố người dùng quên mật khẩu", "Sự cố màn hình bị mờ"], 0,
         "Multi-AZ phân bổ các bản sao ứng dụng và cơ sở dữ liệu trên nhiều trung tâm dữ liệu độc lập về nguồn điện và mạng, đạt tính sẵn sàng cao.", "Day 15 - Slide: Multi-AZ High Availability Architecture"),
        ("AI Vendor SLA Limitations & Risk Mitigation", "SLA cam kết của hầu hết các nhà cung cấp LLM API thương mại (như OpenAI) thường chỉ đạt mức nào và doanh nghiệp cần làm gì để đạt cam kết 99.99% với khách hàng của mình?",
         ["Cam kết 100% không bao giờ lỗi", "Các nhà cung cấp thường chỉ cam kết 99.0% đến 99.9% Uptime (cho phép thời gian chết vài giờ mỗi tháng); Doanh nghiệp bắt buộc phải xây dựng Kiến trúc Đa Đám Mây Đa Nhà Cung Cấp (Multi-Vendor Redundancy) để tự bù đắp khoảng trống SLA", "Không cần làm gì cả", "Khuyên khách hàng không nên dùng ứng dụng vào ban đêm"], 1,
         "Tự xây dựng tầng dự phòng đa nhà cung cấp là con đường duy nhất để doanh nghiệp đạt được cam kết SLA cao hơn chính bản thân từng nhà cung cấp riêng lẻ.", "Day 15 - Slide: Bridging the Vendor SLA Gap"),
        ("Continuous Disaster Recovery Testing (Chaos Engineering)", "Phương pháp 'Chaos Engineering' (như Chaos Monkey) được áp dụng để kiểm thử khả năng phục hồi của hệ thống AI như thế nào?",
         ["Đập phá máy tính vật lý trong văn phòng", "Chủ động và ngẫu nhiên tạo ra các sự cố giả lập trong môi trường Staging/Production (như Đột ngột ngắt kết nối OpenAI API, Làm nghẽn mạng Vector DB, Tắt ngẫu nhiên 50% containers) để kiểm tra xem cơ chế Failover và Circuit Breaker có tự động kích hoạt hoàn hảo hay không", "Cố tình viết sai cú pháp code", "Xóa toàn bộ cơ sở dữ liệu khách hàng"], 1,
         "Chaos Engineering chủ động thử lửa hệ thống trong điều kiện thực tế, biến các phản ứng phục hồi sự cố từ lý thuyết thành năng lực tự động đã được kiểm chứng.", "Day 15 - Slide: Chaos Engineering for AI Resilience"),
        ("Observability Cost Optimization", "Khi chi phí lưu trữ Logs và Traces của hệ thống AI vượt quá 20% tổng chi phí hạ tầng, giải pháp tối ưu hóa nào nên được áp dụng?",
         ["Tắt hoàn toàn hệ thống giám sát", "Áp dụng Quy tắc Phân tầng Lưu trữ Nhật ký (Log Tiering & Tail-based Sampling): Lưu trữ chi tiết 7 ngày trên In-memory SSD, chuyển dữ liệu cũ sang Object Storage S3 dạng nén Parquet, và chỉ giữ lại 100% Trace cho các phiên bị lỗi", "Xóa toàn bộ mã nguồn của ứng dụng", "Chỉ ghi log của người dùng trả phí"], 1,
         "Phân tầng lưu trữ và lấy mẫu thông minh giúp cắt giảm 80% chi phí giám sát mà vẫn bảo toàn đầy đủ các bằng chứng cần thiết cho việc gỡ lỗi và tuân thủ pháp lý.", "Day 15 - Slide: Telemetry Cost Governance"),
        ("Automated Compliance Auditing", "Một hệ thống 'Automated Compliance Pipeline' trong doanh nghiệp tự động thực hiện những tác vụ kiểm toán nào hàng ngày?",
         ["Đếm số lượng nhân viên đi làm đúng giờ", "Tự động quét kho dữ liệu RAG và nhật ký truy vấn để phát hiện các trường hợp vi phạm bản quyền dữ liệu, rò rỉ PII chưa được che giấu, hoặc các phản hồi vượt quá thẩm quyền tư vấn nghiệp vụ", "Tính toán tiền thưởng cho ban giám đốc", "Gửi email chúc mừng sinh nhật khách hàng"], 1,
         "Kiểm toán tuân thủ tự động đảm bảo toàn bộ hoạt động của hệ thống AI luôn nằm trong khuôn khổ pháp lý và chính sách đạo đức của doanh nghiệp.", "Day 15 - Slide: Continuous Compliance & Audit Automation"),
        ("AI Product Retirement & Knowledge Archival", "Khi thay thế hoàn toàn một hệ thống AI cũ bằng một thế hệ AI mới, quy trình lưu trữ tri thức lịch sử (Knowledge Archival) cần đảm bảo điều gì?",
         ["Xóa toàn bộ dữ liệu lịch sử ngay lập tức", "Lưu trữ bản chụp snapshot của toàn bộ Vector Collections, Prompts, Metadata và Bộ kiểm thử đánh giá lịch sử vào kho lưu trữ lạnh (Cold Storage) để phục vụ tra cứu pháp lý hoặc kiểm toán trong tương lai", "In toàn bộ tài liệu ra giấy và đóng bìa cứng", "Gửi toàn bộ dữ liệu cho đối thủ cạnh tranh"], 1,
         "Lưu trữ snapshot lịch sử bảo vệ tài sản tri thức doanh nghiệp và đáp ứng các nghĩa vụ giải trình pháp lý cho các quyết định trong quá khứ.", "Day 15 - Slide: System Decommissioning & Archival"),
        ("Edge-to-Cloud Hybrid Inference Topology", "Trong kiến trúc lai (Hybrid Edge-Cloud Topology), phân bổ tác vụ nào mang lại sự tối ưu toàn diện nhất?",
         ["Chạy toàn bộ mô hình lớn trên điện thoại", "Thực hiện Tiền xử lý dữ liệu, Kiểm duyệt an toàn PII và Trích xuất Embeddings cục bộ tại thiết bị Edge; chỉ gửi các vector ẩn danh và ngữ cảnh cô đọng lên Cloud để Frontier LLM thực hiện các tác vụ suy luận sâu", "Không sử dụng thiết bị Edge", "Chỉ chạy các tác vụ đơn giản trên Cloud"], 1,
         "Kiến trúc lai tận dụng tối đa năng lực bảo mật và tốc độ tức thì của Edge kết hợp sức mạnh suy luận vô hạn của Cloud.", "Day 15 - Slide: Hybrid Edge-Cloud AI Topologies"),
        ("Production Runbook Automation", "Khái niệm 'Automated Runbook' (Sổ tay vận hành tự động) trong quản trị sự cố AI là gì?",
         ["Tập sách giáo khoa in sẵn", "Các kịch bản tự động hóa (Scripts/Workflows) được kích hoạt ngay khi hệ thống giám sát phát hiện sự cố (ví dụ: Tự động khởi động lại container bị nghẽn bộ nhớ, Tự động chuyển mạch sang API dự phòng khi latency vượt ngưỡng)", "Bảng phân công trực ban của kỹ sư", "Lịch họp hàng tuần của công ty"], 1,
         "Runbook tự động hóa rút ngắn thời gian phục hồi dịch vụ (MTTR) từ vài giờ xuống vài giây bằng cách loại bỏ sự chậm trễ của con người trong các tình huống khẩn cấp.", "Day 15 - Slide: Automated Incident Response Runbooks"),
        ("Enterprise Access Control (RBAC/ABAC) for RAG Knowledge Bases", "Sự khác biệt giữa RBAC (Role-Based Access Control) và ABAC (Attribute-Based Access Control) khi phân quyền truy xuất tài liệu trong RAG là gì?",
         ["RBAC chỉ dùng cho hình ảnh; ABAC chỉ dùng cho văn bản", "RBAC phân quyền dựa trên Vai trò cố định của người dùng (e.g. `role: manager`); ABAC phân quyền động và chi tiết hơn dựa trên tập hợp các Thuộc tính (e.g. `user_department == doc_department AND user_clearance_level >= doc_classification AND time_of_day within working_hours`)", "ABAC không hỗ trợ bảo mật", "Cả 2 đều giống hệt nhau"], 1,
         "ABAC cung cấp khả năng kiểm soát truy cập ngữ cảnh linh hoạt và bảo mật cao cấp hơn nhiều so với phân quyền theo vai trò truyền thống.", "Day 15 - Slide: RBAC vs ABAC in Enterprise Knowledge Bases"),
        ("AI Workload Cost Allocation: Multi-Tenant Chargeback", "Trong một tập đoàn lớn có 20 phòng ban cùng sử dụng chung một Nền tảng AI Platform nội bộ, mô hình 'Chargeback / Showback' tính toán chi phí như thế nào?",
         ["Chia đều tổng chi phí cho 20 phòng ban bất kể mức độ sử dụng", "Theo dõi chính xác số lượng Input Tokens, Output Tokens, Thời gian sử dụng GPU và Số lượt gọi API của từng phòng ban qua `department_id` tag trên mọi request để xuất hóa đơn nội bộ minh bạch theo thực tế sử dụng", "Bắt phòng ban IT phải trả toàn bộ chi phí", "Không cần theo dõi chi phí"], 1,
         "Chargeback minh bạch thúc đẩy các phòng ban có ý thức tối ưu hóa chi phí token và phân bổ nguồn lực tài chính công bằng trong toàn tập đoàn.", "Day 15 - Slide: Multi-Tenant AI Cost Allocation & Chargeback"),
        ("Continuous Model Evaluation & Drift Compensation", "Quy trình bù trừ trôi lệch mô hình liên tục (Continuous Drift Compensation) trên Production diễn ra theo chu trình khép kín nào?",
         ["Chờ đến khi hệ thống bị hỏng hoàn toàn", "Giám sát Telemetry -> Phát hiện trôi lệch phân phối dữ liệu (Data Drift) -> Tự động kích hoạt luồng Dynamic Few-shot Retrieval cập nhật các ví dụ mẫu mới nhất vào prompt -> Nếu độ chính xác vẫn chưa đạt chuẩn, kích hoạt Pipeline Fine-Tuning định kỳ trên cụm máy chủ ngầm", "Tắt toàn bộ hệ thống để cài đặt lại từ đầu", "Xóa toàn bộ dữ liệu của người dùng"], 1,
         "Bù trừ trôi lệch tự động kết hợp giữa cập nhật ngữ cảnh động tức thời và tinh chỉnh mô hình định kỳ giúp duy trì chất lượng hệ thống luôn ở đỉnh cao.", "Day 15 - Slide: Continuous Drift Compensation Cycles"),
        ("Enterprise AI Architecture Review Board (ARB)", "Vai trò của 'AI Architecture Review Board' (Hội đồng Thẩm định Kiến trúc AI) trong doanh nghiệp là gì?",
         ["Tổ chức các buổi tiệc liên hoan", "Thẩm định độc lập và phê duyệt các giải pháp kiến trúc AI trước khi triển khai, đảm bảo tính tuân thủ tiêu chuẩn an toàn, khả năng mở rộng quy mô, hiệu quả chi phí và tính tương thích với hạ tầng chung của tập đoàn", "Bình chọn nhân viên xuất sắc của tháng", "Quyết định mức lương của lập trình viên"], 1,
         "Hội đồng thẩm định kiến trúc đóng vai trò chốt chặn kỹ thuật chiến lược, ngăn ngừa các giải pháp manh mún, lãng phí và mất an toàn thông tin trong tổ chức.", "Day 15 - Slide: Enterprise AI Governance & Review Boards")
    ]

    d15_hard = [
        ("Enterprise Mission-Critical AI Platform Master Architecture", "Thiết kế một Bản thiết kế Kiến trúc Tổng thể (Master Architectural Blueprint) cho Nền tảng AI Doanh nghiệp phục vụ 50 triệu người dùng toàn cầu, xử lý 100,000 QPS, hỗ trợ Multi-Tenant, Zero-Downtime, SLA 99.99% và Multi-Region Active-Active. Trình bày chi tiết cấu trúc 6 phân tầng chuẩn mực?",
         ["Chạy một ứng dụng monolithic duy nhất trên 1 máy chủ VPS", "Triển khai 6 Phân tầng Cốt lõi: 1. Global Edge Ingress & WAF (Cloudflare/Route53 Anycast + Rate Limiting + DDoS Protection); 2. Enterprise API Gateway & Auth (Kong/Envoy với OAuth2/OIDC, mTLS, Scoped Quotas & Dynamic Routing); 3. Stateless AI Agent Orchestration Mesh (Kubernetes EKS/GKE Microservices với HPA/Karpenter trên uvloop FastAPI); 4. Distributed Knowledge & Data Layer (Kafka CDC + Delta Lakehouse + Qdrant/Milvus Vector Shards với Storage-Compute Decoupling & Multi-AZ Replicas); 5. Multi-Provider Hybrid Model Serving Tier (Primary Frontier LLMs + vLLM TensorRT Private GPU Clusters với Circuit Breakers); 6. Full-Stack Observability & Governance Control Plane (OpenTelemetry Collector + Prometheus + Jaeger + Phoenix Continuous Eval + Automated PII Redaction)", "Chỉ cần mua một máy tính thật đắt tiền và cắm dây mạng tốc độ cao", "Tắt toàn bộ các lớp bảo mật để đạt tốc độ tối đa"], 1,
         "Kiến trúc tổng thể phân tầng chuẩn mực kết hợp giữa định tuyến biên toàn cầu, điều phối phi trạng thái, hạ tầng dữ liệu phân tán và tầng quan sát an ninh là đỉnh cao của kỹ nghệ AI cấp doanh nghiệp.", "Day 15 - Slide: Master Enterprise AI Architecture Blueprint"),
        ("Zero-Downtime Database Migration under Continuous Write Load", "Khi cần nâng cấp cấu trúc bảng dữ liệu của hệ thống lưu trữ trạng thái Agent (Postgres/Redis State Store) chứa 100 triệu bản ghi đang nhận 5,000 lượt ghi/giây mà không được phép có bất kỳ downtime hay lock bảng nào, phương pháp 'Expand and Contract' (Mở rộng và Thu hẹp) được thực thi như thế nào?",
         ["Chạy lệnh `ALTER TABLE` trực tiếp trên bảng chính và khóa database trong 2 tiếng", "Quy trình 4 giai đoạn: 1. Expand: Thêm cột mới song song với cột cũ và cho phép nhận giá trị null; 2. Dual-Write: Cập nhật ứng dụng để ghi đồng thời dữ liệu vào cả cột cũ và cột mới; 3. Backfill: Chạy tiến trình nền di chuyển dữ liệu lịch sử từ cột cũ sang cột mới theo từng lô nhỏ; 4. Contract: Chuyển đổi ứng dụng sang chỉ đọc/ghi trên cột mới và xóa bỏ an toàn cột cũ", "Tắt database vào ban đêm và copy dữ liệu bằng tay", "Xóa toàn bộ dữ liệu lịch sử và bắt đầu lại từ đầu"], 1,
         "Phương pháp Expand and Contract (hay Parallel Change Pattern) là chuẩn mực vàng trong kỹ nghệ phần mềm để di chuyển cấu trúc dữ liệu quy mô lớn mà hoàn toàn không có downtime.", "Day 15 - Slide: Zero-Downtime Data Migration: Expand and Contract"),
        ("Global Latency Optimization with Distributed Semantic Caching Topologies", "Thiết kế một Mạng lưới Bộ nhớ đệm Ngữ nghĩa Phân tán (Distributed Multi-Region Semantic Cache) phục vụ người dùng tại 15 quốc gia với mục tiêu phục vụ 60% truy vấn tại Edge với độ trễ < 15ms và chi phí $0?",
         ["Đặt một máy chủ cache duy nhất tại Mỹ và bắt tất cả các nước kết nối về", "Triển khai Kiến trúc Edge-First Semantic Cache (Cloudflare Workers / Fastly Compute@Edge kết hợp Upstash Vector / Redis Global Replication): Khi người dùng gửi câu hỏi, Worker tại PoP gần nhất tạo Embedding siêu nhẹ -> Truy vấn Vector Cache cục bộ -> Nếu Cosine Similarity > 0.96, trả về ngay kết quả từ Edge Cache trong 12ms; chỉ các truy vấn Cache Miss mới được chuyển tiếp về Cụm LLM trung tâm", "Bắt người dùng phải tự nhớ câu trả lời cũ", "Không sử dụng bộ nhớ đệm vì sợ dữ liệu bị cũ"], 1,
         "Edge Semantic Caching đưa năng lực xử lý vector tới sát người dùng cuối cùng, giảm thiểu 60% chi phí API và mang lại trải nghiệm phản hồi tức thì mang tính cách mạng.", "Day 15 - Slide: Edge-First Global Semantic Caching Topologies"),
        ("Disaster Recovery: Catastrophic Cloud Outage Failover Strategy", "Khi toàn bộ vùng điện toán đám mây `us-east-1` của AWS bị sập hoàn toàn trong 8 giờ, quy trình Kích hoạt Phục hồi Thảm họa Đa Đám mây (Multi-Cloud Disaster Recovery Failover to GCP) diễn ra theo trình tự tự động nào để đạt RTO < 60s và RPO < 10s?",
         ["Ngồi chờ AWS sửa xong sự cố và giải thích cho khách hàng", "1. Global Health Probes phát hiện sự cố mất liên lạc toàn vùng us-east-1; 2. Global DNS Anycast tự động chuyển mạch 100% lưu lượng sang Cụm GCP us-central1 trong 15 giây; 3. Cụm GCP kích hoạt Read-Replicas của Cơ sở dữ liệu và Vector Store thành Primary; 4. Hệ thống phục hồi trạng thái từ Kafka Cross-Region Mirroring (RPO < 5s); 5. Khởi chạy toàn bộ dịch vụ AI phục vụ bình thường", "Khóc lóc và xin lỗi khách hàng trên truyền thông", "Đóng cửa công ty vĩnh viễn"], 1,
         "Kiến trúc Multi-Cloud Active-Passive với cơ chế đồng bộ dữ liệu liên tục đảm bảo tính sống còn của doanh nghiệp trước các thảm họa sập toàn bộ hạ tầng của một nhà cung cấp đám mây.", "Day 15 - Slide: Multi-Cloud Disaster Recovery & Automated Failover"),
        ("Cost-Quality Optimization via Dynamic Reinforcement Learning Routing", "Thay vì dùng các luật định tuyến cố định, làm thế nào để xây dựng một 'RL-Powered Dynamic Model Router' tự động tối ưu hóa phương trình đa mục tiêu $\\max(\\text{Quality}) - \\lambda \\cdot \\text{Cost} - \\mu \\cdot \\text{Latency}$ theo thời gian thực?",
         ["Chọn ngẫu nhiên một mô hình bất kỳ cho mỗi request", "Sử dụng Thuật toán Multi-Armed Bandit (Contextual Bandit / Thompson Sampling): Thu thập đặc trưng của User Query (Độ phức tạp, Độ dài, Miền tri thức) -> Dự báo xác suất thành công của từng mô hình (GPT-4o, Claude 3.5, SLM cục bộ) -> Định tuyến tới mô hình có kỳ vọng phần thưởng cao nhất; liên tục cập nhật trọng số chính sách dựa trên phản hồi của người dùng và chi phí thực tế", "Luôn gửi tới mô hình đắt tiền nhất để đảm bảo an toàn", "Bắt người dùng tự chọn mô hình và tự trả tiền"], 1,
         "Contextual Bandits tự động tìm ra điểm cân bằng tối ưu giữa chi phí tài chính, thời gian phản hồi và chất lượng câu trả lời cho từng phân khúc truy vấn cụ thể một cách thích ứng.", "Day 15 - Slide: Contextual Bandit Model Routing Optimization"),
        ("Enterprise AI Compliance Architecture for SOC2 Type II and HIPAA", "Một nền tảng AI xử lý dữ liệu hồ sơ bệnh án điện tử (EHR) cần đạt chứng chỉ SOC2 Type II và HIPAA. Thiết kế Kiến trúc Kiểm soát An ninh Toàn diện nào đáp ứng 100% các tiêu chuẩn kiểm toán khắt khe nhất?",
         ["Ký một bản cam kết miệng với khách hàng", "Triển khai Bộ kiểm soát An ninh 5 Chiều: 1. Mã hóa Toàn diện (Encryption in Transit với TLS 1.3 và Encryption at Rest với Customer Managed Keys / AWS KMS HSM); 2. Immutable Audit Logging (Toàn bộ thao tác truy cập dữ liệu được ghi vào S3 WORM Object Lock không thể xóa sửa); 3. Automated PII/PHI De-identification Gateway trước khi dữ liệu chạm tới LLMs; 4. Ký thỏa thuận BAA (Business Associate Agreement) với tất cả các nhà cung cấp mô hình; 5. Kiểm thử xâm nhập độc lập định kỳ (Third-party Pentest)", "Tắt toàn bộ hệ thống lưu trữ nhật ký để tránh bị soi", "Lưu trữ dữ liệu bệnh án trong file Excel công khai"], 1,
         "Bộ kiểm soát an ninh 5 chiều thiết lập khuôn khổ quản trị dữ liệu y tế và tài chính đạt chuẩn kiểm toán quốc tế, bảo vệ doanh nghiệp trước mọi trách nhiệm pháp lý nghiêm ngặt.", "Day 15 - Slide: SOC2 Type II & HIPAA AI Compliance Architecture"),
        ("Autonomous Self-Healing AI Infrastructure", "Khi một Pod phục vụ Agentic Tool bị rò rỉ bộ nhớ (Memory Leak) và bắt đầu phản hồi chậm bất thường (Degraded Performance), cơ chế Tự Phục hồi Tự động (Self-Healing Kubernetes Controller) xử lý như thế nào mà không cần sự can thiệp của kỹ sư trực đêm?",
         ["Để Pod tiếp tục chạy cho đến khi máy chủ sập", "Kubernetes Liveness & Startup Probes tùy biến liên tục theo dõi Tỉ lệ tiêu thụ RAM và Latency p95: Khi phát hiện dấu hiệu suy thoái vượt ngưỡng an toàn trong 3 lần kiểm tra liên tiếp, Controller tự động gắn cờ Unhealthy, rút Pod khỏi danh sách nhận traffic của Service, khởi chạy một Pod mới thay thế khỏe mạnh và tiến hành tiêu hủy an toàn Pod bị lỗi (Automated Eviction & Restart)", "Gửi tin nhắn đánh thức toàn bộ ban giám đốc dậy sửa lỗi", "Khởi động lại toàn bộ mạng internet"], 1,
         "Cơ chế Tự phục hồi tự động của Kubernetes loại bỏ hoàn toàn sự phụ thuộc vào can thiệp thủ công của con người trong việc xử lý các sự cố suy thoái tài nguyên cục bộ.", "Day 15 - Slide: Self-Healing Kubernetes Infrastructure Patterns"),
        ("Capacity Planning & Queueing Theory under Heavy Tail AI Traffic", "Khi thiết kế hạ tầng phục vụ lưu lượng truy cập có phân phối đuôi dài (Heavy-Tail Distributed Traffic: 90% requests ngắn 100 tokens, 10% requests dài 50,000 tokens), mô hình Lý thuyết Xếp hàng (Queueing Theory) nào ngăn chặn hiện tượng nghẽn đầu hàng (Head-of-Line Blocking)?",
         ["Sử dụng một hàng đợi FIFO đơn duy nhất cho tất cả các requests", "Triển khai Mô hình Hàng đợi Phân tầng Đa mức (Multi-Level Priority Queueing / Weighted Fair Queueing): Tách biệt luồng xử lý thành 'Short-Job Fast Lane' (Xử lý các request ngắn với độ trễ thấp) và 'Long-Job Dedicated Pool' (Xử lý các tác vụ xử lý tài liệu dài/nặng với cơ chế phân đoạn bất đồng bộ), đảm bảo các request ngắn không bao giờ bị chặn bởi các tác vụ cồng kềnh", "Bắt tất cả các requests phải chờ theo thứ tự đến trước phục vụ trước", "Từ chối xử lý toàn bộ các requests dài"], 1,
         "Phân tách làn xử lý nhanh cho các tác vụ ngắn (Fair Queueing) là giải pháp kinh điển giải quyết triệt để hiện tượng nghẽn hàng đợi trong các hệ thống phục vụ tải không đồng nhất.", "Day 15 - Slide: Advanced Queueing Theory for Heterogeneous AI Workloads"),
        ("Zero-Trust Cross-Boundary Agent Collaboration Protocol", "Khi 2 AI Agents thuộc 2 tập đoàn đối tác thương mại khác nhau cần phối hợp trao đổi dữ liệu để thực hiện một hợp đồng logistics, giao thức bảo mật Không Tin cậy (Zero-Trust Inter-Enterprise A2A Protocol) nào đảm bảo tính toàn vẹn và không rò rỉ bí mật nội bộ?",
         ["Cho phép Agent của đối tác truy cập trực tiếp vào cơ sở dữ liệu nội bộ", "Triển khai Giao thức Trao đổi An toàn dựa trên Chữ ký số và Hợp đồng Năng lực (Cryptographic Capability-based A2A Gateway): Mọi thông điệp và Tool Call giữa 2 Agent phải được ký số (Ed25519), mã hóa đầu cuối (mTLS), xác thực qua Hợp đồng Ủy quyền có phạm vi hẹp (Scoped Claims) và đi qua Tầng Kiểm duyệt Dữ liệu Ngữ nghĩa (Semantic Data Firewall) để ngăn chặn việc tiết lộ bí mật thương mại ngoài phạm vi hợp đồng", "Tin tưởng tuyệt đối vào Agent của đối tác", "Gửi toàn bộ mã nguồn của Agent cho đối tác"], 1,
         "Zero-Trust A2A Gateway thiết lập ranh giới bảo mật nghiêm ngặt cho phép các tác tử liên doanh nghiệp hợp tác hiệu quả mà không làm phương hại đến bí mật nội bộ của các bên.", "Day 15 - Slide: Zero-Trust Inter-Enterprise Agent Collaboration"),
        ("Continuous Automated Chaos Injection & Resilience Scoring", "Làm thế nào để xây dựng một Khung Chấm điểm Độ Bền vững Hệ thống (Resilience Scorecard) tự động thử lửa hạ tầng AI trên Staging mỗi tuần một lần?",
         ["Hỏi ý kiến của các kỹ sư về độ tự tin", "Sử dụng Automated Chaos Orchestrator (như Chaos Mesh): Tự động kích hoạt chuỗi 20 kịch bản thảm họa có kiểm soát (Mất 50% GPU nodes, Tăng độ trễ mạng lên 500ms, Giả lập lỗi API 429 và 500 từ nhà cung cấp, Cắt đứt kết nối Vector DB) -> Đo lường Tỉ lệ Tự phục hồi thành công (MTTR) và Tỉ lệ câu trả lời Thoái lui An toàn (Fallback Success Rate) để tính toán Điểm số Kháng cự Thảm họa (Resilience Index 0-100)", "Chỉ kiểm tra khi chuẩn bị có đoàn thanh tra", "Tắt toàn bộ hệ thống để bảo trì"], 1,
         "Thử lửa thảm họa tự động định kỳ biến khả năng phục hồi từ một khái niệm trừu tượng thành một chỉ số kỹ thuật có thể đo lường và cải tiến liên tục.", "Day 15 - Slide: Automated Chaos Testing & Resilience Scoring"),
        ("Multi-Modal Streaming Synchronization Architecture", "Trong một ứng dụng AI Giáo dục tương tác thời gian thực đòi hỏi đồng bộ hoàn hảo giữa Dòng Văn bản (Text Stream), Dòng Giọng nói (Audio TTS Stream) và Trực quan hóa Biểu đồ (Interactive UI Visuals), kiến trúc Đồng bộ Thời gian thực (Real-time Multi-Modal Sync Engine) nào đạt chuẩn mượt mà?",
         ["Gửi từng phần riêng lẻ không cần đồng bộ", "Triển khai Giao thức Ghép kênh Đa phương thức dựa trên Khung thời gian (Time-Stamped Multi-Modal Packet Multiplexing over WebSockets/WebRTC): Server gắn kèm các nhãn thời gian đồng bộ (`sync_timestamp` & `phoneme_markers`) vào từng gói tin văn bản, âm thanh và sự kiện UI; Client sử dụng Bộ điều phối Đồng bộ Cục bộ (Local Jitter Buffer & Timeline Scheduler) để phát đồng thời giọng đọc, hiệu ứng gõ chữ và biểu đồ ăn khớp chính xác tới từng mili-giây", "Bắt người dùng tự bấm nút phát âm thanh sau khi đọc xong chữ", "Chỉ hiển thị văn bản và tắt âm thanh"], 1,
         "Timeline Synchronization qua WebSockets/WebRTC đảm bảo sự hòa quyện hoàn hảo giữa thị giác và thính giác, mang lại trải nghiệm tương tác tự nhiên như người thật.", "Day 15 - Slide: Multi-Modal Real-time Synchronization Architecture"),
        ("Post-Quantum Cryptography & Long-Term AI Secret Protection", "Khi chuẩn bị cho kỷ nguyên Máy tính Lượng tử có khả năng bẻ khóa các thuật toán mã hóa khóa công khai truyền thống (RSA/ECC), chiến lược Mã hóa Hậu Lượng tử (Post-Quantum Cryptography - PQC) nào bảo vệ an toàn cho các Kho Tri thức AI tối mật trong 20 năm tới?",
         ["Không cần chuẩn bị vì máy tính lượng tử chưa xuất hiện", "Chuyển đổi toàn bộ Tầng Mã hóa Dữ liệu (Encryption in Transit & at Rest) sang các thuật toán Hậu Lượng tử đạt chuẩn NIST (như ML-KEM / Kyber cho trao đổi khóa và ML-DSA / Dilithium cho chữ ký số) kết hợp Kiến trúc Lai Cổ điển - Hậu lượng tử (Hybrid Classical-PQC Mode) để bảo vệ toàn vẹn các bí mật tri thức cốt lõi trước mối đe dọa 'Thu thập ngay - Giải mã sau' (Harvest Now, Decrypt Later)", "Khóa dữ liệu bằng mật khẩu 100 chữ số", "Chỉ lưu trữ dữ liệu trong đầu của lập trình viên"], 1,
         "Áp dụng sớm các tiêu chuẩn mã hóa hậu lượng tử (PQC) bảo vệ các tài sản tri thức chiến lược của doanh nghiệp khỏi các cuộc tấn công thu thập dữ liệu giải mã trong tương lai.", "Day 15 - Slide: Post-Quantum Cryptography for Long-Term AI Secrets")
    ]
